/* Card set: Minecraft (generated from minecraft-full.csv by package_minecraft.py). */
CardSets.register({"id":"minecraft","name":"Minecraft","code":"MINE","description":"Blocks, items, tools and mobs from the world of Minecraft — creepers, diamonds and dragon eggs. Iconic status sets the rarity.","theme":{"primary":"#5da344","secondary":"#8a5f3c","artBackground":"#f8f9fa","artFit":"contain"},"pack":{"name":"Minecraft Pack","emblem":"⛏️","skin":"minecraft"},"cards":[{"name":"Grass Block","rarity":"chase","id":"grass-block","subtitle":"Block","details":"The block that launched a billion worlds: grass spreads to nearby dirt, and mining it without Silk Touch just gives plain dirt.","image":"https://minecraft.wiki/images/Grass_Block_JE7_BE6.png"},{"name":"Creeper","rarity":"chase","id":"creeper","subtitle":"Mob","details":"Silent until it hisses: this camouflaged creeper sneaks up, flashes white and detonates, and can be defused only by killing it fast.","image":"https://minecraft.wiki/images/Creeper_JE3_BE1.png"},{"name":"Ender Dragon","rarity":"chase","id":"ender-dragon","subtitle":"Mob","details":"The original final boss, perched on obsidian pillars in the End; destroy her healing crystals first, then strike as she swoops.","image":"https://minecraft.wiki/images/Ender_Dragon_JE1_BE1.png"},{"name":"Wither","rarity":"chase","id":"wither","subtitle":"Mob","details":"A build-your-own boss: stack four soul sand in a T, add three wither skeleton skulls, and stand back — it explodes into existence.","image":"https://minecraft.wiki/images/Wither_JE2_BE2.png"},{"name":"Enchanted Golden Apple","rarity":"chase","id":"enchanted-golden-apple","subtitle":"Food","details":"The uncraftable crown jewel (its crafting recipe was removed in 1.9). Eating one grants Absorption IV, Regeneration II and resistances.","image":"assets/sets/compress/minecraft__enchanted-golden-apple.webp"},{"name":"Dragon Egg","rarity":"chase","id":"dragon-egg","subtitle":"Block","details":"The dragon's trophy: it teleports away when touched, and if it falls onto a torch or slab it breaks loose as a collectible item.","image":"https://minecraft.wiki/images/Dragon_Egg_JE5.png"},{"name":"Elytra","rarity":"chase","id":"elytra","subtitle":"Armor","details":"Found only in End ship treasure rooms; wearing these wings turns falling into gliding, and firework rockets give you mid-air thrust.","image":"https://minecraft.wiki/images/Elytra_JE2_BE2.png"},{"name":"Beacon","rarity":"chase","id":"beacon","subtitle":"Block","details":"Crafted from three obsidian, five glass and a nether star; a full pyramid of mineral blocks gives every nearby player buffs.","image":"https://minecraft.wiki/images/Beacon_JE6_BE2.png"},{"name":"Command Block","rarity":"chase","id":"command-block","subtitle":"Block","details":"Unobtainable in legit survival: a creative-only block that runs typed commands when powered, from teleports to spawning mobs.","image":"https://minecraft.wiki/images/Impulse_Command_Block.gif"},{"name":"Netherite Ingot","rarity":"chase","id":"netherite-ingot","subtitle":"Item","details":"Smelt ancient debris into scrap, combine four scrap with four gold, and you get the one ingot that upgrades diamond gear at a smithing table.","image":"https://minecraft.wiki/images/Netherite_Ingot_JE1_BE2.png"},{"name":"Warden","rarity":"legendary","id":"warden","subtitle":"Mob","details":"The blind titan of the deep dark: it hunts by sound and smell, hits harder than the dragon, and scales walls to reach noisy prey.","image":"assets/sets/compress/minecraft__warden.webp"},{"name":"Enderman","rarity":"legendary","id":"enderman","subtitle":"Mob","details":"Tall, shy and terrifying when stared at: looking at its face enrages it, water burns it, and it drops the pearls used to find strongholds.","image":"https://minecraft.wiki/images/Enderman_JE3.png"},{"name":"Villager","rarity":"legendary","id":"villager","subtitle":"Mob","details":"Your trading partner: each villager locks into a profession from a job-site block, restocks twice a day, and zombifies at a discount cure.","image":"https://minecraft.wiki/images/Plains_Villager_Base_JE2.png"},{"name":"Iron Golem","rarity":"legendary","id":"iron-golem","subtitle":"Mob","details":"Built from four iron blocks, a carved pumpkin and pure village loyalty; it patrols for monsters and tosses them skyward with one swing.","image":"https://minecraft.wiki/images/Iron_Golem_JE2_BE2.png"},{"name":"Axolotl","rarity":"legendary","id":"axolotl","subtitle":"Mob","details":"Bred from two tropical fish at a time, these amphibians come in five colours; the blue one is a one-in-256 hatch from regular breeding.","image":"assets/sets/compress/minecraft__axolotl.webp"},{"name":"Steve","rarity":"legendary","id":"steve","subtitle":"Character","details":"The default skin since 2010: a bearded everyman in a cyan shirt whose blocky silhouette became the face of the game itself.","image":"https://minecraft.wiki/images/Steve_%28classic%29_JE6.png"},{"name":"Block of Netherite","rarity":"legendary","id":"block-of-netherite","subtitle":"Block","details":"Nine netherite ingots in one cube: the single most expensive storage block in the game, and it will not burn in lava or fire.","image":"https://minecraft.wiki/images/Block_of_Netherite_JE1_BE1.png"},{"name":"Block of Diamond","rarity":"legendary","id":"block-of-diamond","subtitle":"Block","details":"Nine diamonds compressed into one gleaming cube; expensive flex, beacons' favourite fuel-block, and a very shiny floor tile.","image":"https://minecraft.wiki/images/Block_of_Diamond_JE5_BE3.png"},{"name":"Ancient Debris","rarity":"legendary","id":"ancient-debris","subtitle":"Block","details":"Netherite's source ore: buried in lava-drenched nether depths, immune to explosions, and usually safest to expose with beds or TNT.","image":"https://minecraft.wiki/images/Ancient_Debris_JE1_BE1.png"},{"name":"Bedrock","rarity":"legendary","id":"bedrock","subtitle":"Block","details":"The floor and ceiling of the world: unbreakable in survival, it caps the Overworld, roofs the Nether and floors the End's void.","image":"https://minecraft.wiki/images/Bedrock_JE2_BE2.png"},{"name":"Diamond Ore","rarity":"legendary","id":"diamond-ore","subtitle":"Block","details":"Before deepslate existed this was the dream find at lava level; one ore block, one gem, and Fortune can stretch it to four.","image":"https://minecraft.wiki/images/Diamond_Ore_JE5_BE5.png"},{"name":"Enchanting Table","rarity":"legendary","id":"enchanting-table","subtitle":"Block","details":"Three diamonds, obsidian and a book on top: surround it with bookshelves (15 for max power) to unlock level-30 enchantments.","image":"assets/sets/compress/minecraft__enchanting-table.gif"},{"name":"Conduit","rarity":"legendary","id":"conduit","subtitle":"Block","details":"Crafted from a Heart of the Sea ringed by eight nautilus shells; underwater it grants Conduit Power and zaps hostile mobs nearby.","image":"https://minecraft.wiki/images/Conduit_JE1_BE1.png"},{"name":"Nether Star","rarity":"legendary","id":"nether-star","subtitle":"Item","details":"The Wither's parting gift, dropped every single kill; it is the irreplaceable core ingredient at the heart of every beacon.","image":"assets/sets/compress/minecraft__nether-star.webp"},{"name":"Totem of Undying","rarity":"legendary","id":"totem-of-undying","subtitle":"Item","details":"Dropped by evokers in woodland mansions and raids; hold one when fatal damage lands and it shatters instead, restoring you to 1 HP.","image":"https://minecraft.wiki/images/Totem_of_Undying_JE2_BE2.png"},{"name":"Diamond","rarity":"legendary","id":"diamond","subtitle":"Item","details":"The aqua gem that defines mid-game wealth: mined from ore, dug from deepslate, or traded from a wandering trader's rare stock.","image":"https://minecraft.wiki/images/Diamond_JE3_BE3.png"},{"name":"Heart of the Sea","rarity":"legendary","id":"heart-of-the-sea","subtitle":"Item","details":"The treasure at the bottom of a buried-treasure chest, found only with a map from a shipwreck or ocean ruins; the heart of a conduit.","image":"https://minecraft.wiki/images/Heart_of_the_Sea_JE1_BE2.png"},{"name":"End Crystal","rarity":"legendary","id":"end-crystal","subtitle":"Item","details":"Crafted from an eye of ender, a ghast tear and seven glass; placed on the exit portal, four of them resurrect the Ender Dragon.","image":"assets/sets/compress/minecraft__end-crystal.webp"},{"name":"Enchanted Book","rarity":"legendary","id":"enchanted-book","subtitle":"Item","details":"Written at an enchanting table or fished up as treasure, it carries one enchantment in portable form, ready to marry to gear on an anvil.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Diamond Sword","rarity":"legendary","id":"diamond-sword","subtitle":"Weapon","details":"Five diamonds' worth of bragging rights in blade form: the classic endgame sword before netherite existed, and still an icon.","image":"https://minecraft.wiki/images/Diamond_Sword_JE3_BE3.png"},{"name":"Netherite Pickaxe","rarity":"legendary","id":"netherite-pickaxe","subtitle":"Tool","details":"The upgraded king of tools: a diamond pickaxe plus one netherite ingot mines almost anything and shrugs off lava if dropped.","image":"https://minecraft.wiki/images/Netherite_Pickaxe_JE3_BE2.png"},{"name":"Trident","rarity":"legendary","id":"trident","subtitle":"Weapon","details":"The drowned's prize weapon: thrown like a spear, enchanted with Loyalty it flies back to your hand, and it skewers aquatic mobs.","image":"https://minecraft.wiki/images/Trident.png"},{"name":"Mace","rarity":"legendary","id":"mace","subtitle":"Weapon","details":"Smith one from a heavy core and a breeze rod (a 1.21 drop pairing): slow to swing, but its damage scales with how far you fall.","image":"https://minecraft.wiki/images/Mace_JE1_BE1.png"},{"name":"Mending","rarity":"legendary","id":"mending","subtitle":"Enchantment","details":"The most requested enchantment in the game: it lets XP slowly repair the item carrying it, so treasured gear never has to break.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Cat","rarity":"legendary","id":"cat-disc","subtitle":"Music Disc","details":"C418's gentle, jazzy signature tune. Drops when a skeleton's arrow fells a creeper, and also turns up in dungeon and mansion chests.","image":"https://minecraft.wiki/images/Music_Disc_cat_JE1_BE1.png"},{"name":"Stal","rarity":"legendary","id":"stal","subtitle":"Music Disc","details":"C418's moody, crackling slow-burn. Drops from creepers felled by a skeleton's arrow, or from dungeon and woodland mansion chests.","image":"https://minecraft.wiki/images/Music_Disc_stal_JE1_BE1.png"},{"name":"Pigstep","rarity":"legendary","id":"pigstep","subtitle":"Music Disc","details":"Lena Raine's funky, bass-heavy banger, looted only from bastion remnant chests in the Nether, where piglins guard it jealously.","image":"https://minecraft.wiki/images/Music_Disc_Pigstep_JE1_BE1.png"},{"name":"The Nether","rarity":"legendary","id":"the-nether","subtitle":"Dimension","details":"A warped, warped place: soul fire burns blue, hoglins charge, and beds explode if you dare to sleep. Bring gold or be attacked.","image":"assets/sets/compress/minecraft__the-nether.webp"},{"name":"The End","rarity":"legendary","id":"the-end","subtitle":"Dimension","details":"The dragon's domain: a floating island of end stone ringed by void, where chorus fruit teleports you and shulkers guard the loot.","image":"assets/sets/compress/minecraft__the-end.webp"},{"name":"Ancient City","rarity":"legendary","id":"ancient-city","subtitle":"Structure","details":"A buried deep-dark metropolis of sculk and soul lanterns; sneak, because three shrieker alarms summon the Warden.","image":"assets/sets/compress/minecraft__ancient-city.webp"},{"name":"Woodland Mansion","rarity":"legendary","id":"woodland-mansion","subtitle":"Structure","details":"The biggest generated house in the game: three floors of illager-occupied rooms, hidden loot rooms, and a rooftop garden.","image":"https://minecraft.wiki/images/Woodland_Mansion.png"},{"name":"Ocean Monument","rarity":"legendary","id":"ocean-monument","subtitle":"Structure","details":"A prismarine fortress on the ocean floor guarded by laser-firing guardians; three elder guardians inflict Mining Fatigue inside.","image":"assets/sets/compress/minecraft__ocean-monument.webp"},{"name":"Trial Chambers","rarity":"legendary","id":"trial-chambers","subtitle":"Structure","details":"Underground vaults of tuff and copper where spinning trial spawners scale their mob waves and rewards to your party size.","image":"assets/sets/compress/minecraft__trial-chambers.webp"},{"name":"Elder Guardian","rarity":"epic","id":"elder-guardian","subtitle":"Mob","details":"The spiked elder of the monument: bigger, greyer and meaner than its kin, it beams you from range and curses you with Mining Fatigue III.","image":"assets/sets/compress/minecraft__elder-guardian.webp"},{"name":"Wither Skeleton","rarity":"epic","id":"wither-skeleton","subtitle":"Mob","details":"Drops the skulls needed to summon the Wither, three at a time if you're lucky; its coal drops fuel a furnace surprisingly well.","image":"https://minecraft.wiki/images/Wither_Skeleton_JE4_BE3.png"},{"name":"Piglin Brute","rarity":"epic","id":"piglin-brute","subtitle":"Mob","details":"The raid captain's enforcer: it guards a golden axe, hits like a truck in melee, and drops emeralds and its ominous banner.","image":"https://minecraft.wiki/images/Piglin_Brute_JE1.png"},{"name":"Evoker","rarity":"epic","id":"evoker","subtitle":"Mob","details":"A robed illager who summons fang traps and vexes, heals itself, and drops a Totem of Undying every time it is killed.","image":"https://minecraft.wiki/images/Evoker_Summoning_Vexes.png"},{"name":"Ravager","rarity":"epic","id":"ravager","subtitle":"Mob","details":"The raid's battering ram: a huge armoured beast with a knockback charge that players can ride only after its rider is slain.","image":"https://minecraft.wiki/images/Ravager_JE1.png"},{"name":"Breeze","rarity":"epic","id":"breeze","subtitle":"Mob","details":"A trial-chamber whirlwind that fires wind charges, deflects projectiles, and drops the breeze rods used to craft the mace.","image":"https://minecraft.wiki/images/Breeze_BE1_JE2.webp"},{"name":"Creaking","rarity":"epic","id":"creaking","subtitle":"Mob","details":"It cannot be fought: if you move, it stands perfectly still, and only attacks when no one is looking at it. Handle by torchlight patience.","image":"https://minecraft.wiki/images/Creaking_JE1_BE1.png"},{"name":"Sniffer","rarity":"epic","id":"sniffer","subtitle":"Mob","details":"A giant two-legged sniffer that digs up ancient seeds — torchflower and pitcher plant — which exist nowhere else in the wild.","image":"https://minecraft.wiki/images/Sniffer_sniffsniff.gif"},{"name":"Allay","rarity":"epic","id":"allay","subtitle":"Mob","details":"A flying blue helper summoned by note blocks: it fetches matching items you hand it and delivers them with a happy dance.","image":"https://minecraft.wiki/images/Allay_JE2_BE2.gif"},{"name":"Alex","rarity":"epic","id":"alex","subtitle":"Character","details":"The slim-armed default skin added in 2014: an orange-haired counterpart to Steve, modelled with narrower 3-pixel arms.","image":"https://minecraft.wiki/images/Alex_%28slim%29_JE3.png"},{"name":"Emerald Ore","rarity":"epic","id":"emerald-ore","subtitle":"Block","details":"The rarest ore of the classic set: single-vein spawns in mountain biomes made it a trophy long before deepslate variants existed.","image":"https://minecraft.wiki/images/Emerald_Ore_JE4_BE3.png"},{"name":"Block of Emerald","rarity":"epic","id":"block-of-emerald","subtitle":"Block","details":"Nine emeralds in a cube: the official currency block of villager trade empires, and a beacon pyramid's most expensive option.","image":"https://minecraft.wiki/images/Block_of_Emerald_JE4_BE3.png"},{"name":"Reinforced Deepslate","rarity":"epic","id":"reinforced-deepslate","subtitle":"Block","details":"Found only ringing the central frame of an ancient city; nearly blast-proof, yet a piston can still shove it along.","image":"https://minecraft.wiki/images/Reinforced_Deepslate_JE1_BE1.png"},{"name":"Spawner","rarity":"epic","id":"spawner","subtitle":"Block","details":"A cage with a tiny spinning mob inside that spawns waves of that mob when a player comes near; even Silk Touch cannot harvest it.","image":"https://minecraft.wiki/images/Monster_Spawner_JE4.png"},{"name":"Crying Obsidian","rarity":"epic","id":"crying-obsidian","subtitle":"Block","details":"Obsidian weeping purple tears: found in ruined portals, it respawns you in the Nether once charged with glowstone — or explodes.","image":"https://minecraft.wiki/images/Crying_Obsidian_JE1_BE1.png"},{"name":"Netherite Sword","rarity":"epic","id":"netherite-sword","subtitle":"Weapon","details":"One tier above diamond, forged not mined: it never burns in lava, so your best blade survives the drop that kills everything else.","image":"https://minecraft.wiki/images/Netherite_Sword_JE2_BE2.png"},{"name":"Diamond Pickaxe","rarity":"epic","id":"diamond-pickaxe","subtitle":"Tool","details":"The beloved blue workhorse: fast, durable and enchantable, it is the pickaxe most players carry for most of their playthrough.","image":"https://minecraft.wiki/images/Diamond_Pickaxe_JE3_BE3.png"},{"name":"Crossbow","rarity":"epic","id":"crossbow","subtitle":"Weapon","details":"Loaded with arrows or fireworks, it draws slower than a bow but hits harder, and Piercing or Multishot turn it into a crowd tool.","image":"https://minecraft.wiki/images/Crossbow.png"},{"name":"Netherite Armor","rarity":"epic","id":"netherite-armor","subtitle":"Armor","details":"A full suit forged by upgrading diamond: knockback-resistant, lava-proof, and the most expensive outfit in survival Minecraft.","image":"https://minecraft.wiki/images/Netherite_Chestplate_JE2_BE1.png"},{"name":"Diamond Armor","rarity":"epic","id":"diamond-armor","subtitle":"Armor","details":"The iconic cyan suit: four pieces of pure diamond flex that defined 'endgame armour' for a decade of players.","image":"https://minecraft.wiki/images/Diamond_Chestplate_JE3_BE2.png"},{"name":"Golden Apple","rarity":"epic","id":"golden-apple","subtitle":"Food","details":"Crafted from eight gold ingots and an apple, it heals four hunger and two hearts — and piglins will stop and admire its shine.","image":"https://minecraft.wiki/images/Golden_Apple_JE2_BE2.png"},{"name":"Eye of Ender","rarity":"epic","id":"eye-of-ender","subtitle":"Item","details":"An ender pearl plus blaze powder: throw it at a stronghold and it flies toward the End portal, sometimes shattering on landing.","image":"https://minecraft.wiki/images/Eye_of_Ender_JE2_BE2.png"},{"name":"Shulker Shell","rarity":"epic","id":"shulker-shell","subtitle":"Item","details":"Two of these purple shells and a chest craft a shulker box — the backpack chest that keeps its contents when broken and carried.","image":"https://minecraft.wiki/images/Shulker_Shell_JE2_BE2.png"},{"name":"Echo Shard","rarity":"epic","id":"echo-shard","subtitle":"Item","details":"Ancient city treasure used to craft disc '5' and the Recovery Compass, which points to the spot where you last died.","image":"https://minecraft.wiki/images/Echo_Shard_JE1_BE1.png"},{"name":"Fortune","rarity":"epic","id":"fortune","subtitle":"Enchantment","details":"The miner's blessing: each level multiplies ore drops on average, turning a single diamond vein into a small fortune.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Silk Touch","rarity":"epic","id":"silk-touch","subtitle":"Enchantment","details":"Grab the block itself instead of its drop: grass, spawners... almost — it lifts ores, glass and ice whole instead of breaking them.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Stronghold","rarity":"epic","id":"stronghold","subtitle":"Structure","details":"Every world hides one in stone bricks below a library; its silverfish-infested portal room is the only road to the End.","image":"assets/sets/compress/minecraft__stronghold.webp"},{"name":"13","rarity":"epic","id":"disc-13","subtitle":"Music Disc","details":"C418's eerie cave-sound collage, the first disc added. Dropped by creepers shot by skeletons; it sounds like something is following you.","image":"https://minecraft.wiki/images/Music_Disc_13_JE1_BE1.png"},{"name":"11","rarity":"epic","id":"disc-11","subtitle":"Music Disc","details":"C418's broken, skipping nightmare of a track that cuts off mid-static; a creeper-drop disc wrapped in two decades of playground lore.","image":"https://minecraft.wiki/images/Music_Disc_11_JE2_BE2.png"},{"name":"5","rarity":"epic","id":"disc-5","subtitle":"Music Disc","details":"Samuel Åberg's fragmented soundscape, assembled from nine disc fragments found in ancient city chests — craft the pieces to hear it.","image":"https://minecraft.wiki/images/Music_Disc_5_JE1_BE1.png"},{"name":"Otherside","rarity":"epic","id":"otherside","subtitle":"Music Disc","details":"Lena Raine's bright, hopeful two-sided theme; found in stronghold, dungeon and ancient city chests, it feels like sunrise in the End.","image":"https://minecraft.wiki/images/Music_Disc_otherside_JE1_BE1.png"},{"name":"Relic","rarity":"epic","id":"relic","subtitle":"Music Disc","details":"Aaron Cherof's dusty, nostalgic waltz, dug out by brushing suspicious gravel in trail ruins — archaeology's own record.","image":"https://minecraft.wiki/images/Music_Disc_Relic_JE1_BE1.png"},{"name":"Ghast","rarity":"rare","id":"ghast","subtitle":"Mob","details":"A floating white balloon of misery that screams fireballs at you; kill one and its tear can brew a potion of regeneration.","image":"https://minecraft.wiki/images/Ghast_JE3_BE3.gif"},{"name":"Blaze","rarity":"rare","id":"blaze","subtitle":"Mob","details":"A burning rod-dancer wreathed in smoke; it shoots triple fireballs and drops the blaze rods that power brewing and End travel.","image":"assets/sets/compress/minecraft__blaze.webp"},{"name":"Witch","rarity":"rare","id":"witch","subtitle":"Mob","details":"A swamp-hut hermit who hurls splash potions of harming and poison, then heals herself with potions of healing when hurt.","image":"assets/sets/compress/minecraft__witch.webp"},{"name":"Shulker","rarity":"rare","id":"shulker","subtitle":"Mob","details":"A living jack-in-the-box that hides in its shell, fires homing bullets that make you levitate, and guards End city loot.","image":"https://minecraft.wiki/images/Shulker_JE1_BE1.png"},{"name":"Guardian","rarity":"rare","id":"guardian","subtitle":"Mob","details":"A one-eyed reef sentinel that fires a heat-beam from its spikes; when killed it drops prismarine and sometimes a wet sponge's dreams.","image":"assets/sets/compress/minecraft__guardian.webp"},{"name":"Phantom","rarity":"rare","id":"phantom","subtitle":"Mob","details":"A leathery End-sky manta that swoops on players who skip sleep for three nights, repairing nothing and ruining every rooftop build.","image":"assets/sets/compress/minecraft__phantom.webp"},{"name":"Hoglin","rarity":"rare","id":"hoglin","subtitle":"Mob","details":"The Nether's charging boar-beast, breedable with crimson fungi and a source of porkchops and leather, hostile unless fed or fenced.","image":"https://minecraft.wiki/images/Hoglin_JE3.png"},{"name":"Bee","rarity":"rare","id":"bee","subtitle":"Mob","details":"Striped, territorial and allergic to angering: disturb the hive or harvest without a campfire's smoke and the whole swarm wakes furious.","image":"https://minecraft.wiki/images/Baby_Bee_JE2.gif"},{"name":"Wolf","rarity":"rare","id":"wolf","subtitle":"Mob","details":"Tamed with bones into a loyal hunting companion whose collar can be dyed; it teleports to your side and growls at your enemies.","image":"https://minecraft.wiki/images/Wolf_JE2_BE2.png"},{"name":"Panda","rarity":"rare","id":"panda","subtitle":"Mob","details":"The bamboo-munching show-off with six personalities, from lazy to playful to aggressive; feed it bamboo and it rolls over happily.","image":"https://minecraft.wiki/images/Panda_JE1_BE1.png"},{"name":"Dolphin","rarity":"rare","id":"dolphin","subtitle":"Mob","details":"It leads you to sunken treasure with a happy spin, tosses items your way, and can be boosted by holding a treasure map in its path.","image":"assets/sets/compress/minecraft__dolphin.webp"},{"name":"Mooshroom","rarity":"rare","id":"mooshroom","subtitle":"Mob","details":"A cow colonised by mushrooms: shear it for a normal cow, milk it for mushroom stew, and watch it bloom red or brown with flowers.","image":"https://minecraft.wiki/images/Red_Mooshroom_JE5_BE3.png"},{"name":"Camel","rarity":"rare","id":"camel","subtitle":"Mob","details":"A two-seater desert ship with a built-in saddle hump; it can carry two riders and dash-jump across ravines when fed cactus.","image":"https://minecraft.wiki/images/Camel_Idle.gif"},{"name":"Armadillo","rarity":"rare","id":"armadillo","subtitle":"Mob","details":"It deflects most projectiles with a tink of its shell, hides inside when scared, and scutes drop from babies raised on seagrass.","image":"https://minecraft.wiki/images/Armadillo_JE2_BE2.png"},{"name":"Ender Chest","rarity":"rare","id":"ender-chest","subtitle":"Block","details":"27 slots of dimension-proof storage: break it with Silk Touch to move it, without it you still get eight obsidian back.","image":"assets/sets/compress/minecraft__ender-chest.webp"},{"name":"Anvil","rarity":"rare","id":"anvil","subtitle":"Block","details":"Smithing gear used to cost XP here; drop an item to repair or rename it, but beware the anvil's own fall damage and 'too expensive' cap.","image":"https://minecraft.wiki/images/Anvil_%28N%29_JE3.png"},{"name":"Brewing Stand","rarity":"rare","id":"brewing-stand","subtitle":"Block","details":"Nine glass bottles of potion potential standing over a blaze-powder flame; cauldron water and blaze powder fuel every brew.","image":"https://minecraft.wiki/images/Brewing_Stand_%28empty%29_JE10.png"},{"name":"Jukebox","rarity":"rare","id":"jukebox","subtitle":"Block","details":"Feed it a music disc and it broadcasts that track to everyone within about 65 blocks; hoppers can swap the disc automatically.","image":"https://minecraft.wiki/images/Jukebox_JE2_BE2.png"},{"name":"TNT","rarity":"rare","id":"tnt","subtitle":"Block","details":"Eight logs' worth of party trick: primed by flint, redstone or a flaming arrow, it is griefing, mining and creeper-farming in one.","image":"https://minecraft.wiki/images/TNT_JE3_BE2.png"},{"name":"Obsidian","rarity":"rare","id":"obsidian","subtitle":"Block","details":"Formed when lava meets water, this blast-resistant staple builds nether portals, wither cages and blast chambers everywhere.","image":"https://minecraft.wiki/images/Obsidian_JE3_BE2.png"},{"name":"Glowstone","rarity":"rare","id":"glowstone","subtitle":"Block","details":"It grows on the Nether ceiling and lights a cave with a warm sparkle; nine shards make glowstone dust for potions and lamps.","image":"https://minecraft.wiki/images/Glowstone_JE4_BE2.png"},{"name":"Magma Block","rarity":"rare","id":"magma-block","subtitle":"Block","details":"Magma's overworld cousin... actually pure Nether: it damages steppers without sneaking, never burns up, and lights underwater.","image":"assets/sets/compress/minecraft__magma-block.webp"},{"name":"Block of Iron","rarity":"rare","id":"block-of-iron","subtitle":"Block","details":"Nine iron ingots in a cube: beacon pyramids, golem construction, and the most satisfying clank in any storage room.","image":"https://minecraft.wiki/images/Block_of_Iron_JE4_BE3.png"},{"name":"Block of Gold","rarity":"rare","id":"block-of-gold","subtitle":"Block","details":"Nine gold ingots in a cube: piglins admire it, bells and powered rails chain from it, and a full pyramid is peak flex.","image":"https://minecraft.wiki/images/Block_of_Gold_JE6_BE3.png"},{"name":"Block of Redstone","rarity":"rare","id":"block-of-redstone","subtitle":"Block","details":"Nine redstone dust lines in one block act as a full-strength power source that never depletes — compact wiring's best friend.","image":"https://minecraft.wiki/images/Block_of_Redstone_JE2_BE2.png"},{"name":"Sea Lantern","rarity":"rare","id":"sea-lantern","subtitle":"Block","details":"A naturally glowing sea prismarine frame that lights ocean monuments' treasure rooms and makes a beautiful underwater lamp.","image":"https://minecraft.wiki/images/Sea_Lantern_JE1.gif"},{"name":"Bow","rarity":"rare","id":"bow","subtitle":"Weapon","details":"The hunter's starter: three sticks, three string, and a pull-and-release arc that makes skeletons jealous of your range.","image":"https://minecraft.wiki/images/Bow_JE2_BE1.png"},{"name":"Iron Sword","rarity":"rare","id":"iron-sword","subtitle":"Weapon","details":"The workhorse blade of the mid-game: cheap to craft, fast, and strong enough to carry you until diamonds replace it.","image":"https://minecraft.wiki/images/Iron_Sword_JE2_BE2.png"},{"name":"Diamond Axe","rarity":"rare","id":"diamond-axe","subtitle":"Tool","details":"Three diamonds and two sticks make the axe that both fells forests and, in the right hands, out-damages a diamond sword per swing.","image":"https://minecraft.wiki/images/Diamond_Axe_JE3_BE3.png"},{"name":"Shield","rarity":"rare","id":"shield","subtitle":"Armor","details":"Crafted from six planks and an iron ingot: it blocks most frontal damage and negates knockback, but an axe swing disables it for a few seconds.","image":"https://minecraft.wiki/images/Shield_JE2_BE1.png"},{"name":"Spyglass","rarity":"rare","id":"spyglass","subtitle":"Item","details":"Two copper ingots and an amethyst shard make a pocket telescope with a square view; zooming slows you, so scout from safety.","image":"https://minecraft.wiki/images/Spyglass_JE2_BE1.png"},{"name":"Saddle","rarity":"rare","id":"saddle","subtitle":"Item","details":"Right-click a tamed horse and suddenly it is a vehicle; long treasure-only, saddles are finally craftable — three leather and an iron ingot.","image":"https://minecraft.wiki/images/Saddle_%28Pig%29_JE2_BE2.png"},{"name":"Name Tag","rarity":"rare","id":"name-tag","subtitle":"Item","details":"An anvil and four iron give it a name; name a mob and it never despawns, name it Dinnerbone and it flips upside down forever.","image":"https://minecraft.wiki/images/Name_Tag_JE3_BE2.png"},{"name":"Lead","rarity":"rare","id":"lead","subtitle":"Item","details":"Two string and a slimeball leash almost any animal to your hand or a fence post — just don't stretch it past ten blocks.","image":"https://minecraft.wiki/images/Lead_JE2_BE2.png"},{"name":"Firework Rocket","rarity":"rare","id":"firework-rocket","subtitle":"Item","details":"Climb on gunpowder, paper and a firework star: it launches you skyward, and strapped to elytra it becomes a rocket engine.","image":"https://minecraft.wiki/images/Firework_Rocket_JE2_BE2.png"},{"name":"Dragon's Breath","rarity":"rare","id":"dragons-breath","subtitle":"Item","details":"Breathe on a lingering-cloud... bottled from an Ender Dragon's breath attack with an empty bottle, it brews splash potions into lingering ones.","image":"https://minecraft.wiki/images/Dragon%27s_Breath_JE2_BE2.png"},{"name":"Phantom Membrane","rarity":"rare","id":"phantom-membrane","subtitle":"Item","details":"An elytra's repair kit and a phantom's drop; four of them at an anvil restore a quarter of a wingsuit's durability.","image":"https://minecraft.wiki/images/Phantom_Membrane_JE2_BE2.png"},{"name":"Nautilus Shell","rarity":"rare","id":"nautilus-shell","subtitle":"Item","details":"Conduit's currency: these spiral shells hide in buried treasure, warm oceans and the pockets of drowned holding them like trophies.","image":"https://minecraft.wiki/images/Nautilus_Shell_JE1_BE2.png"},{"name":"Blaze Rod","rarity":"rare","id":"blaze-rod","subtitle":"Item","details":"A blaze's burning core: ground into powder it fuels brewing stands, builds eyes of ender and lights the road to the End.","image":"https://minecraft.wiki/images/Blaze_Rod_JE1_BE1.png"},{"name":"Ghast Tear","rarity":"rare","id":"ghast-tear","subtitle":"Item","details":"The ghost's unlikely loot: a single tear brews a regeneration potion, and four respawn an end crystal on the portal.","image":"https://minecraft.wiki/images/Ghast_Tear_JE2_BE2.png"},{"name":"Golden Carrot","rarity":"rare","id":"golden-carrot","subtitle":"Food","details":"Carrots never looked richer: eight gold nuggets around one carrot restores more saturation than almost any other food.","image":"https://minecraft.wiki/images/Golden_Carrot_JE4_BE2.png"},{"name":"Cake","rarity":"rare","id":"cake","subtitle":"Food","details":"Egg, wheat, sugar and milk baked into a placeable feast; right-click for a slice, seven slices a cake, zero crumbs wasted.","image":"https://minecraft.wiki/images/Cake_JE4.png"},{"name":"Suspicious Stew","rarity":"rare","id":"suspicious-stew","subtitle":"Food","details":"One bowl, random flower, random effect: most grant a helpful buff for a few seconds — or a blindness stew you'll regret.","image":"https://minecraft.wiki/images/Suspicious_Stew_JE1_BE1.png"},{"name":"Potion of Strength","rarity":"rare","id":"potion-of-strength","subtitle":"Potion","details":"Brewed by adding blaze powder to an awkward potion; it adds flat melee damage per hit for three minutes, longer with redstone.","image":"https://minecraft.wiki/images/Potion_of_Strength_JE3.png"},{"name":"Potion of Fire Resistance","rarity":"rare","id":"potion-of-fire-resistance","subtitle":"Potion","details":"Brewed with a magma cream in an awkward potion: eight minutes of lava-proof confidence, extendable but not stackable.","image":"https://minecraft.wiki/images/Potion_of_Fire_Resistance_JE3.png"},{"name":"Sharpness","rarity":"rare","id":"sharpness","subtitle":"Enchantment","details":"Each of its five levels adds flat damage to a blade's swing, and it sharpens axes into surprisingly serious weapons too.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Looting","rarity":"rare","id":"looting","subtitle":"Enchantment","details":"Kills drop more — much more: wither skeletons drop skulls more often, and a Looting III sword turns mob farms generous.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Nether Fortress","rarity":"rare","id":"nether-fortress","subtitle":"Structure","details":"The Nether's great bridge-fortress of nether brick, home to blazes and wither skeletons and the nether wart every brewer needs.","image":"assets/sets/compress/minecraft__nether-fortress.webp"},{"name":"Bastion Remnant","rarity":"rare","id":"bastion-remnant","subtitle":"Structure","details":"A blackstone stronghold in lava lakes, defended by piglin brutes; its treasure rooms hold the Pigstep disc and netherite scraps.","image":"assets/sets/compress/minecraft__bastion-remnant.webp"},{"name":"End City","rarity":"rare","id":"end-city","subtitle":"Structure","details":"A purple city at the world's edge where shulkers levitate you between ships; the elytra hangs in one ship's treasure room.","image":"assets/sets/compress/minecraft__end-city.webp"},{"name":"Blocks","rarity":"rare","id":"blocks","subtitle":"Music Disc","details":"C418's bouncy, upbeat groove — like building something cheerful. Drops from creepers felled by skeletons or from dungeon loot.","image":"https://minecraft.wiki/images/Music_Disc_blocks_JE1_BE1.png"},{"name":"Chirp","rarity":"rare","id":"chirp","subtitle":"Music Disc","details":"C418's playful, almost music-box instrumental. It drops from creepers shot by skeletons and surfaces in woodland mansions.","image":"https://minecraft.wiki/images/Music_Disc_chirp_JE1_BE1.png"},{"name":"Strad","rarity":"rare","id":"strad","subtitle":"Music Disc","details":"C418's sweeping, sunlit electronic piece. Drops from creepers downed by a skeleton's arrow, a true trophy of the classic set.","image":"https://minecraft.wiki/images/Music_Disc_strad_JE1_BE1.png"},{"name":"Ward","rarity":"rare","id":"ward","subtitle":"Music Disc","details":"C418's suspenseful, building storm of a track. Drops from creepers shot by skeletons and appears in dungeon chests.","image":"https://minecraft.wiki/images/Music_Disc_ward_JE1_BE1.png"},{"name":"Creator","rarity":"rare","id":"creator","subtitle":"Music Disc","details":"Lena Raine's grand, orchestral showpiece, drawn from trial chamber ominous vaults that only open for ominous trial keys.","image":"https://minecraft.wiki/images/Music_Disc_Creator_JE1_BE1.png"},{"name":"Precipice","rarity":"rare","id":"precipice","subtitle":"Music Disc","details":"Aaron Cherof's ominous, majestic march; it drops only from trial chamber vaults, often after the last spawner falls.","image":"https://minecraft.wiki/images/Music_Disc_Precipice_JE1_BE1.png"},{"name":"Tears","rarity":"rare","id":"tears","subtitle":"Music Disc","details":"Amos Roddy's melancholy piano disc, quick and aching; it drops only from a player killing a Happy Ghast with a reflected attack.","image":"https://minecraft.wiki/images/Music_Disc_Tears_JE1_BE1.png"},{"name":"Zombie","rarity":"uncommon","id":"zombie","subtitle":"Mob","details":"Burns in sunlight and drops rotten flesh. Some spawn with armor or weapons, and villagers it kills can become zombie villagers.","image":"https://minecraft.wiki/images/Zombie_JE5_BE2.png"},{"name":"Skeleton","rarity":"uncommon","id":"skeleton","subtitle":"Mob","details":"A bow-wielding undead that strafes while shooting and burns in sunlight. Drops bones and arrows, and sometimes its bow.","image":"https://minecraft.wiki/images/Lefthandedskeleton.png"},{"name":"Spider","rarity":"uncommon","id":"spider","subtitle":"Mob","details":"Climbs walls and leaps at prey; its eyes glow in the dark. Neutral in bright light, it drops string and sometimes a spider eye.","image":"https://minecraft.wiki/images/Spider_JE5_BE4.png"},{"name":"Cave Spider","rarity":"uncommon","id":"cave-spider","subtitle":"Mob","details":"A smaller, faster spider whose bite poisons. Found around spawners in abandoned mineshafts, it drops string and spider eyes.","image":"https://minecraft.wiki/images/Cave_Spider_JE3_BE3.png"},{"name":"Zombie Villager","rarity":"uncommon","id":"zombie-villager","subtitle":"Mob","details":"Cured back into a villager with a golden apple and a potion of weakness. Spawns naturally or when a zombie kills a villager.","image":"https://minecraft.wiki/images/Plains_Zombie_Villager_Base_JE1.png"},{"name":"Drowned","rarity":"uncommon","id":"drowned","subtitle":"Mob","details":"An underwater zombie found in oceans and rivers; some carry tridents. Zombies submerged in water convert into drowned.","image":"https://minecraft.wiki/images/Drowned_JE2.png"},{"name":"Husk","rarity":"uncommon","id":"husk","subtitle":"Mob","details":"A desert zombie that does not burn in sunlight and inflicts Hunger with its hits. Drops rotten flesh, rarely iron or potatoes.","image":"https://minecraft.wiki/images/Husk_JE4_BE2.png"},{"name":"Stray","rarity":"uncommon","id":"stray","subtitle":"Mob","details":"A snowy-biome skeleton that shoots tipped arrows of Slowness. Burns in sunlight and drops bones, arrows, and sometimes a bow.","image":"https://minecraft.wiki/images/Stray_JE2_BE4.png"},{"name":"Pillager","rarity":"uncommon","id":"pillager","subtitle":"Mob","details":"A crossbow-carrying illager found at outposts and in patrols. Its captains drop ominous bottles, used to start raids and trial omens.","image":"https://minecraft.wiki/images/Pillager_JE3.png"},{"name":"Vindicator","rarity":"uncommon","id":"vindicator","subtitle":"Mob","details":"An axe-wielding illager in woodland mansions and raids. It charges fast, disables shields, and drops emeralds and iron axes.","image":"https://minecraft.wiki/images/Vindicator_attacking.png"},{"name":"Slime","rarity":"uncommon","id":"slime","subtitle":"Mob","details":"A hopping cube that splits into smaller slimes when killed, dropping slimeballs. Spawns in swamps and in certain slime chunks.","image":"https://minecraft.wiki/images/Slime_JE3_BE2.png"},{"name":"Magma Cube","rarity":"uncommon","id":"magma-cube","subtitle":"Mob","details":"The Nether's hopping cube; it splits when killed, ignores fall and fire damage, and drops magma cream.","image":"https://minecraft.wiki/images/Magma_Cube_JE2_BE2.png"},{"name":"Piglin","rarity":"uncommon","id":"piglin","subtitle":"Mob","details":"Gold-loving Nether folk who barter with gold ingots. Hostile if you wear no gold armor or open chests near them.","image":"https://minecraft.wiki/images/Piglin_JE1.png"},{"name":"Zombified Piglin","rarity":"uncommon","id":"zombified-piglin","subtitle":"Mob","details":"Neutral unless provoked, then nearby zombified piglins swarm the attacker. Drops gold nuggets and rotten flesh.","image":"https://minecraft.wiki/images/Zombified_Piglin_JE9.png"},{"name":"Endermite","rarity":"uncommon","id":"endermite","subtitle":"Mob","details":"A tiny hostile bug that sometimes appears when an ender pearl lands. Endermen attack it, and it despawns after two minutes.","image":"https://minecraft.wiki/images/Endermite.gif"},{"name":"Silverfish","rarity":"uncommon","id":"silverfish","subtitle":"Mob","details":"Hides inside infested stone in strongholds and mountains. When hurt, it wakes nearby silverfish to swarm the attacker.","image":"https://minecraft.wiki/images/Silverfish_JE1_BE1.png"},{"name":"Vex","rarity":"uncommon","id":"vex","subtitle":"Mob","details":"A tiny flying illager summoned by evokers. It phases through walls with an iron sword and turns red before striking.","image":"assets/sets/compress/minecraft__vex.gif"},{"name":"Goat","rarity":"uncommon","id":"goat","subtitle":"Mob","details":"A mountain climber that leaps high, rams other mobs, and sometimes drops a goat horn when it rams a hard block.","image":"https://minecraft.wiki/images/Goat_%28two_horns%29_JE1_BE1.png"},{"name":"Frog","rarity":"uncommon","id":"frog","subtitle":"Mob","details":"Swamp frogs eat small slimes and magma cubes, producing froglights. Tadpoles grow into variants set by their biome's temperature.","image":"https://minecraft.wiki/images/Temperate_Frog_JE1_BE1.gif"},{"name":"Fox","rarity":"uncommon","id":"fox","subtitle":"Mob","details":"A shy taiga hunter that carries items in its mouth, pounces on prey in snow, and drops what it holds when fed sweet berries.","image":"https://minecraft.wiki/images/Fox_JE1_BE1.png"},{"name":"Cat","rarity":"uncommon","id":"cat","subtitle":"Mob","details":"A tamable village animal fed raw cod or salmon. Tamed cats scare off creepers and phantoms and bring morning gifts.","image":"https://minecraft.wiki/images/Jellie_Cat.png"},{"name":"Horse","rarity":"uncommon","id":"horse","subtitle":"Mob","details":"Tamable and rideable, with speed, health, and jump strength varying by horse. Can wear horse armor and be bred with golden food.","image":"https://minecraft.wiki/images/White_Horse.png"},{"name":"Llama","rarity":"uncommon","id":"llama","subtitle":"Mob","details":"A tamable pack animal that spits at attackers and can carry a chest. Leashed llamas form caravans of up to ten animals.","image":"https://minecraft.wiki/images/White_Llama_JE2_BE2.png"},{"name":"Parrot","rarity":"uncommon","id":"parrot","subtitle":"Mob","details":"A jungle bird tamed with seeds. It mimics nearby mob sounds, dances by jukeboxes, and can ride on a player's shoulder.","image":"https://minecraft.wiki/images/Red_Parrot_JE1_BE1.png"},{"name":"Crafting Table","rarity":"uncommon","id":"crafting-table","subtitle":"Block","details":"Crafted from four planks, it opens the 3x3 crafting grid used for most tools, weapons, armor, and advanced blocks.","image":"https://minecraft.wiki/images/Crafting_Table_JE4_BE3.png"},{"name":"Furnace","rarity":"uncommon","id":"furnace","subtitle":"Block","details":"Crafted from eight cobblestone, it smelts ores and cooks food with fuel such as coal, charcoal, lava, or wood.","image":"https://minecraft.wiki/images/Furnace_%28S%29_JE4.png"},{"name":"Blast Furnace","rarity":"uncommon","id":"blast-furnace","subtitle":"Block","details":"Smelts ores, tools, and armor twice as fast as a furnace, using five iron ingots, a furnace, and three smooth stone. Armorer's workstation.","image":"https://minecraft.wiki/images/Blast_Furnace_%28S%29_JE1.png"},{"name":"Smoker","rarity":"uncommon","id":"smoker","subtitle":"Block","details":"Cooks food twice as fast as a furnace and is a butcher's workstation. Crafted from a furnace surrounded by four logs.","image":"https://minecraft.wiki/images/Smoker_%28S%29_JE2.png"},{"name":"Chest","rarity":"uncommon","id":"chest","subtitle":"Block","details":"Crafted from eight planks, it stores 27 stacks; two side by side form a large chest holding 54. Can be trapped or locked.","image":"https://minecraft.wiki/images/Chest.gif"},{"name":"Barrel","rarity":"uncommon","id":"barrel","subtitle":"Block","details":"Stores 27 stacks like a single chest and works as a fisherman's workstation. Crafted from six planks and two wooden slabs.","image":"https://minecraft.wiki/images/Barrel_%28U%29_JE1_BE1.png"},{"name":"Hopper","rarity":"uncommon","id":"hopper","subtitle":"Block","details":"Moves items between containers one at a time, pulling from above and pushing below. Crafted from five iron ingots and a chest.","image":"https://minecraft.wiki/images/Hopper_%28D%29_JE8.png"},{"name":"Dispenser","rarity":"uncommon","id":"dispenser","subtitle":"Block","details":"When powered by redstone, it uses items: shooting arrows, placing water, or firing splash potions. Unlike a dropper, it acts.","image":"https://minecraft.wiki/images/Dispenser_%28S%29_JE4.png"},{"name":"Piston","rarity":"uncommon","id":"piston","subtitle":"Block","details":"Powered by redstone, it pushes blocks and entities up to 12 blocks away. It cannot push obsidian or bedrock.","image":"https://minecraft.wiki/images/Piston_%28U%29_JE3.gif"},{"name":"Sticky Piston","rarity":"uncommon","id":"sticky-piston","subtitle":"Block","details":"A piston coated with a slimeball: it pushes blocks like a piston and pulls its front block back when it retracts.","image":"https://minecraft.wiki/images/Sticky_Piston_%28U%29_JE3.gif"},{"name":"Observer","rarity":"uncommon","id":"observer","subtitle":"Block","details":"Detects block changes in front of it and emits a redstone pulse, enabling clocks, traps, and automatic farms. Uses quartz.","image":"https://minecraft.wiki/images/Observer_JE4_BE3.png"},{"name":"Lectern","rarity":"uncommon","id":"lectern","subtitle":"Block","details":"Holds one book for many readers and works as a librarian's workstation. Its redstone signal depends on the page last viewed.","image":"https://minecraft.wiki/images/Lectern_%28S%29.png"},{"name":"Bookshelf","rarity":"uncommon","id":"bookshelf","subtitle":"Block","details":"Powers an enchanting table: 15 bookshelves around it unlock level 30 enchantments. Broken without Silk Touch, it drops books.","image":"https://minecraft.wiki/images/Bookshelf_JE4_BE2.png"},{"name":"Cauldron","rarity":"uncommon","id":"cauldron","subtitle":"Block","details":"Holds water, lava, or powder snow and can strip dye from leather armor and banners. Filled by buckets or dripping pointed dripstone.","image":"https://minecraft.wiki/images/Cauldron_JE8.png"},{"name":"Bell","rarity":"uncommon","id":"bell","subtitle":"Block","details":"The village meeting point. Ringing it during a raid makes raiders glow briefly and sends villagers running indoors.","image":"https://minecraft.wiki/images/Bell_%28N%29.png"},{"name":"Lantern","rarity":"uncommon","id":"lantern","subtitle":"Block","details":"Crafted from a torch and eight iron nuggets, it hangs or sits on blocks at light level 15; the blue soul variant is dimmer, at level 10.","image":"https://minecraft.wiki/images/Lantern_JE1_BE1.gif"},{"name":"End Stone","rarity":"uncommon","id":"end-stone","subtitle":"Block","details":"The pale stone forming most of the End. Highly blast-resistant and ignored by the ender dragon, it needs a pickaxe to mine.","image":"https://minecraft.wiki/images/End_Stone_JE3_BE2.png"},{"name":"Netherrack","rarity":"uncommon","id":"netherrack","subtitle":"Block","details":"The Nether's common red stone. Fire lit on top of it burns forever, and it is mined quickly with any pickaxe.","image":"https://minecraft.wiki/images/Netherrack_JE4_BE2.png"},{"name":"Soul Sand","rarity":"uncommon","id":"soul-sand","subtitle":"Block","details":"Slows movement on top and makes rising bubble columns in water. Four soul sand in a T with three wither skulls summons the Wither.","image":"https://minecraft.wiki/images/Soul_Sand_JE2_BE2.png"},{"name":"Basalt","rarity":"uncommon","id":"basalt","subtitle":"Block","details":"Found in basalt deltas and from lava meeting ice beside soul soil. Polished basalt makes a smooth, dark building stone.","image":"https://minecraft.wiki/images/Basalt_%28UD%29_JE1_BE1.png"},{"name":"Blackstone","rarity":"uncommon","id":"blackstone","subtitle":"Block","details":"The Nether's cobblestone equivalent from bastions and basalt deltas; it can be crafted into stone tools and furnaces.","image":"https://minecraft.wiki/images/Blackstone_JE3_BE2.png"},{"name":"Prismarine","rarity":"uncommon","id":"prismarine","subtitle":"Block","details":"Ocean monument stone from prismarine shards and crystals dropped by guardians. Its color slowly shifts as it sits placed.","image":"https://minecraft.wiki/images/Prismarine_JE2_BE2.gif"},{"name":"Purpur Block","rarity":"uncommon","id":"purpur-block","subtitle":"Block","details":"End-city block smelted from chorus fruit after popping it. It crafts pillars, stairs, and slabs in pale End purple.","image":"https://minecraft.wiki/images/Purpur_Block_JE2_BE2.png"},{"name":"Pumpkin","rarity":"uncommon","id":"pumpkin","subtitle":"Block","details":"Grows from pumpkin stems on farmland. Carve it with shears, bake it into pie, or in carved form use it to build snow and iron golems.","image":"https://minecraft.wiki/images/Pumpkin_JE3.png"},{"name":"Carved Pumpkin","rarity":"uncommon","id":"carved-pumpkin","subtitle":"Block","details":"A pumpkin carved with shears. Worn as a helmet, or combined with snow or iron blocks to build snow and iron golems.","image":"https://minecraft.wiki/images/Carved_Pumpkin_%28S%29_JE5.png"},{"name":"Jack o'Lantern","rarity":"uncommon","id":"jack-olantern","subtitle":"Block","details":"A carved pumpkin lit with a torch, giving light level 15 even underwater and serving as the head for snow and iron golems when carved first.","image":"https://minecraft.wiki/images/Jack_o%27Lantern_%28S%29_JE4.png"},{"name":"Hay Bale","rarity":"uncommon","id":"hay-bale","subtitle":"Block","details":"Nine wheat compressed into one bale. It heals and breeds horses, cuts fall damage by 80%, and boosts campfire smoke signals.","image":"https://minecraft.wiki/images/Hay_Bale_%28UD%29_JE3_BE3.png"},{"name":"Honey Block","rarity":"uncommon","id":"honey-block","subtitle":"Block","details":"Made from four honey bottles. It sticks to blocks and entities, slows movement and jumping, and slides things along when pushed.","image":"https://minecraft.wiki/images/Honey_Block_JE1_BE2.png"},{"name":"Slime Block","rarity":"uncommon","id":"slime-block","subtitle":"Block","details":"Made from nine slimeballs. Entities bounce on it with no fall damage, and pistons can use it to pull neighboring blocks along.","image":"https://minecraft.wiki/images/Slime_Block_JE2_BE3.png"},{"name":"Sponge","rarity":"uncommon","id":"sponge","subtitle":"Block","details":"Soaks up water around it, turning into a wet sponge that must be smelted dry to reuse. Found in ocean monuments and from elder guardians.","image":"https://minecraft.wiki/images/Sponge_JE3_BE3.png"},{"name":"Iron Ore","rarity":"uncommon","id":"iron-ore","subtitle":"Block","details":"Mined with a stone pickaxe or better, it drops raw iron. Most plentiful high in mountains and in large underground veins.","image":"https://minecraft.wiki/images/Iron_Ore_JE6_BE4.png"},{"name":"Gold Ore","rarity":"uncommon","id":"gold-ore","subtitle":"Block","details":"Needs an iron pickaxe and drops raw gold. Extra common in badlands; its Nether counterpart grows in the Nether's gold-rich biomes.","image":"https://minecraft.wiki/images/Gold_Ore_JE7_BE4.png"},{"name":"Redstone Ore","rarity":"uncommon","id":"redstone-ore","subtitle":"Block","details":"Deep underground ore that glows when touched. An iron pickaxe drops four or five redstone dust, more with Fortune.","image":"https://minecraft.wiki/images/Redstone_Ore_JE4_BE3.png"},{"name":"Lapis Ore","rarity":"uncommon","id":"lapis-ore","subtitle":"Block","details":"Found in a narrow deep band, it drops several lapis lazuli per block with a stone pickaxe or better; Fortune yields more.","image":"https://minecraft.wiki/images/Lapis_Lazuli_Ore_JE4_BE4.png"},{"name":"Copper Ore","rarity":"uncommon","id":"copper-ore","subtitle":"Block","details":"Drops two to five raw copper with a stone pickaxe or better. Huge copper veins run through dripstone caves with granite.","image":"https://minecraft.wiki/images/Copper_Ore_JE2_BE2.png"},{"name":"Coal Ore","rarity":"uncommon","id":"coal-ore","subtitle":"Block","details":"The most common ore, found at almost any height. Mined with any pickaxe, it drops coal for torches and furnace fuel.","image":"https://minecraft.wiki/images/Coal_Ore_JE5_BE4.png"},{"name":"Iron Ingot","rarity":"uncommon","id":"iron-ingot","subtitle":"Item","details":"Smelted from raw iron, it is the workhorse metal: tools, armor, rails, buckets, and nine ingots make a block of iron.","image":"https://minecraft.wiki/images/Iron_Ingot_JE3_BE2.png"},{"name":"Gold Ingot","rarity":"uncommon","id":"gold-ingot","subtitle":"Item","details":"Smelted from raw gold, it crafts golden food, powered rails, and clocks, and it is the currency piglins barter for.","image":"https://minecraft.wiki/images/Gold_Ingot_JE4_BE2.png"},{"name":"Copper Ingot","rarity":"uncommon","id":"copper-ingot","subtitle":"Item","details":"Smelted from raw copper, it crafts lightning rods, spyglasses, and brushes. Copper blocks oxidize from orange to green over time.","image":"https://minecraft.wiki/images/Copper_Ingot_JE2_BE1.png"},{"name":"Emerald","rarity":"uncommon","id":"emerald","subtitle":"Item","details":"Villager currency, obtained mainly by trading and rarely from mountain emerald ore. Nine make a block of emerald.","image":"https://minecraft.wiki/images/Emerald_JE3_BE3.png"},{"name":"Redstone Dust","rarity":"uncommon","id":"redstone-dust","subtitle":"Item","details":"The wiring of redstone circuits, placed as dust lines on blocks. In brewing, it extends a potion's duration.","image":"https://minecraft.wiki/images/Redstone_Dust_JE2_BE2.png"},{"name":"Lapis Lazuli","rarity":"uncommon","id":"lapis-lazuli","subtitle":"Item","details":"A deep-blue gem from lapis ore, spent at the enchanting table (one to three per enchantment) and used as blue dye.","image":"https://minecraft.wiki/images/Lapis_Lazuli_JE2_BE2.png"},{"name":"Nether Quartz","rarity":"uncommon","id":"nether-quartz","subtitle":"Item","details":"Mined from Nether quartz ore, it builds observers, comparators, and daylight detectors, and crafts smooth white quartz blocks.","image":"https://minecraft.wiki/images/Nether_Quartz_JE2_BE2.png"},{"name":"Amethyst Shard","rarity":"uncommon","id":"amethyst-shard","subtitle":"Item","details":"Broken from fully grown amethyst clusters in geodes, yielding four shards for spyglasses, tinted glass, and duplicating allays.","image":"https://minecraft.wiki/images/Amethyst_Shard_JE2_BE1.png"},{"name":"Ender Pearl","rarity":"uncommon","id":"ender-pearl","subtitle":"Item","details":"Dropped by endermen. Throwing one teleports you where it lands at a small health cost; pearls can also trigger End gateways.","image":"https://minecraft.wiki/images/Ender_Pearl_JE3_BE2.png"},{"name":"Iron Pickaxe","rarity":"uncommon","id":"iron-pickaxe","subtitle":"Tool","details":"Three iron ingots and two sticks; 250 durability. It mines diamond, gold, and redstone ores that stone picks cannot harvest.","image":"https://minecraft.wiki/images/Iron_Pickaxe_JE3_BE2.png"},{"name":"Iron Axe","rarity":"uncommon","id":"iron-axe","subtitle":"Tool","details":"Three iron ingots and two sticks; 250 durability. It chops fast, deals heavy axe damage, and its hits can disable a shield.","image":"https://minecraft.wiki/images/Iron_Axe_JE5_BE2.png"},{"name":"Iron Shovel","rarity":"uncommon","id":"iron-shovel","subtitle":"Tool","details":"One iron ingot and two sticks; 250 durability. Best for dirt, sand, and gravel, and right-clicking dirt makes a dirt path.","image":"https://minecraft.wiki/images/Iron_Shovel_JE3_BE2.png"},{"name":"Golden Sword","rarity":"uncommon","id":"golden-sword","subtitle":"Weapon","details":"Two gold ingots and a stick, but only 32 durability: gold breaks fast yet takes high-level enchantments more readily than any tier.","image":"https://minecraft.wiki/images/Golden_Sword_JE3_BE2.png"},{"name":"Iron Armor","rarity":"uncommon","id":"iron-armor","subtitle":"Armor","details":"A full set needs 24 iron ingots and gives 15 armor points, solid mid-game protection that outlasts gold and chainmail.","image":"https://minecraft.wiki/images/Iron_Chestplate_JE2_BE2.png"},{"name":"Golden Armor","rarity":"uncommon","id":"golden-armor","subtitle":"Armor","details":"A full set needs 24 gold ingots but gives only 11 armor points and low durability; piglins leave gold-wearing players alone.","image":"https://minecraft.wiki/images/Golden_Chestplate_JE2_BE2.png"},{"name":"Chainmail Armor","rarity":"uncommon","id":"chainmail-armor","subtitle":"Armor","details":"A full set gives 12 armor points, between leather and iron. It cannot be crafted; get it from mob drops, trading, or loot.","image":"https://minecraft.wiki/images/Chainmail_Chestplate_JE3_BE2.png"},{"name":"Fishing Rod","rarity":"uncommon","id":"fishing-rod","subtitle":"Tool","details":"Three sticks and two string, 64 durability. Its bobber reels in fish, junk, and rare treasure; it can also pull items and mobs.","image":"https://minecraft.wiki/images/Fishing_Rod_JE2_BE2.png"},{"name":"Flint and Steel","rarity":"uncommon","id":"flint-and-steel","subtitle":"Tool","details":"Iron ingot plus flint, 64 uses. It lights fires, nether portals, TNT, and creepers, and can burn away webs and leaves fast.","image":"https://minecraft.wiki/images/Flint_and_Steel_JE4_BE2.png"},{"name":"Shears","rarity":"uncommon","id":"shears","subtitle":"Tool","details":"Two iron ingots, 238 durability. Shears harvest leaves, vines, and grass intact and strip wool from sheep without killing them.","image":"https://minecraft.wiki/images/Shears_JE2_BE2.png"},{"name":"Bucket","rarity":"uncommon","id":"bucket","subtitle":"Item","details":"Three iron ingots make a bucket that carries water, lava, or milk, scoops powder snow, and can hold fish, axolotls, and tadpoles.","image":"https://minecraft.wiki/images/Bucket_JE2_BE2.png"},{"name":"Water Bucket","rarity":"uncommon","id":"water-bucket","subtitle":"Item","details":"A bucket of water places a source block, extinguishes fire, turns lava to obsidian, and landing in its water cancels fall damage.","image":"https://minecraft.wiki/images/Water_Bucket_JE2_BE2.png"},{"name":"Lava Bucket","rarity":"uncommon","id":"lava-bucket","subtitle":"Item","details":"A bucket of lava places flowing lava and is the longest-burning furnace fuel, smelting 100 items per bucket.","image":"https://minecraft.wiki/images/Lava_Bucket_JE2_BE2.png"},{"name":"Milk Bucket","rarity":"uncommon","id":"milk-bucket","subtitle":"Item","details":"Milk taken from cows, mooshrooms, or goats. Drinking it removes all status effects, good and bad, including poison and Wither.","image":"https://minecraft.wiki/images/Milk_Bucket_JE2_BE2.png"},{"name":"Compass","rarity":"uncommon","id":"compass","subtitle":"Item","details":"Four iron ingots and redstone dust. Its needle points to the world spawn point, or to a lodestone it has been linked with.","image":"https://minecraft.wiki/images/Compass_JE3_BE3.gif"},{"name":"Clock","rarity":"uncommon","id":"clock","subtitle":"Item","details":"Four gold ingots and redstone dust. Its dial shows the sun or moon's position, even from underground, the Nether, or the End.","image":"https://minecraft.wiki/images/Clock_JE3_BE3.gif"},{"name":"Cooked Beef","rarity":"uncommon","id":"cooked-beef","subtitle":"Food","details":"Cooked from raw beef in a furnace or over a campfire, steak restores eight hunger and high saturation: a top staple food.","image":"https://minecraft.wiki/images/Steak_JE4_BE3.png"},{"name":"Cooked Porkchop","rarity":"uncommon","id":"cooked-porkchop","subtitle":"Food","details":"Cooked pork restores eight hunger and high saturation, matching steak. Pigs and hoglins that die burning drop it ready-made.","image":"https://minecraft.wiki/images/Cooked_Porkchop_JE4_BE3.png"},{"name":"Cooked Chicken","rarity":"uncommon","id":"cooked-chicken","subtitle":"Food","details":"Cooked chicken restores six hunger. Chickens killed by fire drop it cooked, and foxes prize it enough to steal it.","image":"https://minecraft.wiki/images/Cooked_Chicken_JE3_BE3.png"},{"name":"Cooked Mutton","rarity":"uncommon","id":"cooked-mutton","subtitle":"Food","details":"Cooked mutton restores six hunger with better saturation than chicken. Sheep drop raw mutton, cooked if they die burning.","image":"https://minecraft.wiki/images/Cooked_Mutton_JE3_BE2.png"},{"name":"Baked Potato","rarity":"uncommon","id":"baked-potato","subtitle":"Food","details":"A potato baked in a furnace, smoker, or campfire restores five hunger, a reliable early food that stacks unlike stews.","image":"https://minecraft.wiki/images/Baked_Potato_JE4_BE2.png"},{"name":"Pumpkin Pie","rarity":"uncommon","id":"pumpkin-pie","subtitle":"Food","details":"Crafted from pumpkin, an egg, and sugar, it restores eight hunger with no cooking, though its saturation is low.","image":"https://minecraft.wiki/images/Pumpkin_Pie_JE2_BE2.png"},{"name":"Mushroom Stew","rarity":"uncommon","id":"mushroom-stew","subtitle":"Food","details":"A bowl with red and brown mushrooms restores six hunger. It does not stack, and mooshrooms can be milked for it with a bowl.","image":"https://minecraft.wiki/images/Mushroom_Stew_JE2_BE2.png"},{"name":"Honey Bottle","rarity":"uncommon","id":"honey-bottle","subtitle":"Food","details":"Bottled from a hive or nest with an empty bottle, it restores six hunger and removes poison without clearing other effects.","image":"https://minecraft.wiki/images/Honey_Bottle_JE1_BE2.png"},{"name":"Glow Berries","rarity":"uncommon","id":"glow-berries","subtitle":"Food","details":"Sweet-tasting berries from cave vines in lush caves, restoring two hunger. The glowing vines light the cave and feed foxes.","image":"https://minecraft.wiki/images/Glow_Berries_JE1_BE1.png"},{"name":"Chorus Fruit","rarity":"uncommon","id":"chorus-fruit","subtitle":"Food","details":"End fruit restoring four hunger that teleports the eater randomly up to eight blocks, sometimes through walls and floors.","image":"https://minecraft.wiki/images/Chorus_Fruit_JE2_BE2.png"},{"name":"Potion of Healing","rarity":"uncommon","id":"potion-of-healing","subtitle":"Potion","details":"Brewed with a glistering melon slice in an awkward potion, it heals instantly; glowstone strengthens it to Healing II.","image":"https://minecraft.wiki/images/Potion_of_Healing_JE2.png"},{"name":"Potion of Swiftness","rarity":"uncommon","id":"potion-of-swiftness","subtitle":"Potion","details":"Brewed with sugar in an awkward potion, it raises movement speed by 20%; glowstone makes Swiftness II at 40%.","image":"https://minecraft.wiki/images/Potion_of_Swiftness_JE3.png"},{"name":"Potion of Night Vision","rarity":"uncommon","id":"potion-of-night-vision","subtitle":"Potion","details":"Brewed with a golden carrot in an awkward potion, it gives full brightness in darkness and underwater for clearer sight.","image":"https://minecraft.wiki/images/Potion_of_Night_Vision_JE3.png"},{"name":"Efficiency","rarity":"uncommon","id":"efficiency","subtitle":"Enchantment","details":"Levels I-V for tools and weapons: each level speeds up block breaking, and level V lets diamond tools carve stone almost instantly.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Unbreaking","rarity":"uncommon","id":"unbreaking","subtitle":"Enchantment","details":"Levels I-III for gear: each use of the item has a chance to skip durability loss, stretching a tool's or armor's life.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Protection","rarity":"uncommon","id":"protection","subtitle":"Enchantment","details":"Armor enchantment, levels I-IV: each level reduces most incoming damage, but it conflicts with Fire, Blast, and Projectile Protection.","image":"assets/sets/compress/minecraft__enchanted-book.webp"},{"name":"Village","rarity":"uncommon","id":"village","subtitle":"Structure","details":"Clusters of houses, job sites, and a meeting bell where villagers trade, breed, and summon iron golems. Each biome has its own style.","image":"assets/sets/compress/minecraft__village.webp"},{"name":"Desert Temple","rarity":"uncommon","id":"desert-temple","subtitle":"Structure","details":"A sandstone pyramid hiding four chests under its patterned floor; the central pressure plate sits on a pit of nine TNT.","image":"assets/sets/compress/minecraft__desert-temple.webp"},{"name":"Jungle Temple","rarity":"uncommon","id":"jungle-temple","subtitle":"Structure","details":"A mossy cobblestone temple with a lever puzzle guarding one chest and arrow-shooting dispensers guarding another.","image":"assets/sets/compress/minecraft__jungle-temple.webp"},{"name":"Pillager Outpost","rarity":"uncommon","id":"pillager-outpost","subtitle":"Structure","details":"A dark oak watchtower where pillagers spawn, with loot in a top chest and sometimes a caged iron golem nearby to free.","image":"https://minecraft.wiki/images/Pillager_Outpost.png"},{"name":"Ocean","rarity":"uncommon","id":"ocean","subtitle":"Biome","details":"Vast water biomes in warm, cold, frozen, and deep variants, hiding ocean monuments, shipwrecks, ruins, kelp, and coral in warm seas.","image":"assets/sets/compress/minecraft__ocean.webp"},{"name":"Desert","rarity":"uncommon","id":"desert","subtitle":"Biome","details":"A dry sand biome of cacti, dead bushes, desert villages, wells, and temples. No rain ever falls, and husks and rabbits roam it.","image":"assets/sets/compress/minecraft__desert.webp"},{"name":"Mushroom Fields","rarity":"uncommon","id":"mushroom-fields","subtitle":"Biome","details":"A rare island biome carpeted in mycelium where no hostile mobs spawn naturally. Mooshrooms are its only native animal.","image":"assets/sets/compress/minecraft__mushroom-fields.webp"},{"name":"Deep Dark","rarity":"uncommon","id":"deep-dark","subtitle":"Biome","details":"A cavern biome below y=0 in deepslate, coated in sculk. Its darkness hides ancient cities and the warden they can summon.","image":"assets/sets/compress/minecraft__deep-dark.webp"},{"name":"Far","rarity":"uncommon","id":"far","subtitle":"Music Disc","details":"C418's Far: a calm, airy electronic journey. Drops when a skeleton kills a creeper, or from dungeon chests.","image":"https://minecraft.wiki/images/Music_Disc_far_JE1_BE1.png"},{"name":"Mall","rarity":"uncommon","id":"mall","subtitle":"Music Disc","details":"C418's Mall: a gentle, piano-led piece with a relaxed sway. Drops when a skeleton kills a creeper, or from dungeon chests.","image":"https://minecraft.wiki/images/Music_Disc_mall_JE1_BE1.png"},{"name":"Mellohi","rarity":"uncommon","id":"mellohi","subtitle":"Music Disc","details":"C418's Mellohi: a slow, moody waltz with a haunted edge. Drops when a skeleton kills a creeper, or from dungeon chests.","image":"https://minecraft.wiki/images/Music_Disc_mellohi_JE1_BE1.png"},{"name":"Wait","rarity":"uncommon","id":"wait","subtitle":"Music Disc","details":"C418's Wait: a bright, laid-back track with jazzy warmth. Drops when a skeleton kills a creeper, or from dungeon chests.","image":"https://minecraft.wiki/images/Music_Disc_wait_JE1_BE1.png"},{"name":"Creator (Music Box)","rarity":"uncommon","id":"creator-music-box","subtitle":"Music Disc","details":"Lena Raine's Creator (Music Box): a delicate music-box take on Creator, found in decorated pots in trial chambers.","image":"https://minecraft.wiki/images/Music_Disc_Creator_%28Music_Box%29_JE1_BE1.png"},{"name":"Lava Chicken","rarity":"uncommon","id":"lava-chicken","subtitle":"Music Disc","details":"Hyper Potions' Lava Chicken: a frantic chicken-jockey anthem tied to the Minecraft movie song, all springy bounce and comic urgency.","image":"https://minecraft.wiki/images/Music_Disc_Lava_Chicken_JE1_BE1.png"},{"name":"Pig","rarity":"common","id":"pig","subtitle":"Mob","details":"Passive mob bred with carrots, potatoes or beetroot. Drops raw porkchop and, if saddled, can be steered with a carrot on a stick.","image":"https://minecraft.wiki/images/Temperate_Pig_JE4_BE2.png"},{"name":"Cow","rarity":"common","id":"cow","subtitle":"Mob","details":"Passive mob that drops raw beef and leather when killed. Can be milked with a bucket and bred with wheat.","image":"https://minecraft.wiki/images/Cow_JE7_BE4.png"},{"name":"Sheep","rarity":"common","id":"sheep","subtitle":"Mob","details":"Passive mob grown for wool, which can be dyed and sheared. Eating grass regrows its coat; it also drops raw mutton.","image":"https://minecraft.wiki/images/White_Sheep_JE5.png"},{"name":"Chicken","rarity":"common","id":"chicken","subtitle":"Mob","details":"Passive bird that drops raw chicken and feathers and lays an egg every 5 to 10 minutes. Bred and tempted with seeds.","image":"https://minecraft.wiki/images/Chicken_JE2_BE2.png"},{"name":"Rabbit","rarity":"common","id":"rabbit","subtitle":"Mob","details":"Shy passive mob found in deserts, flower forests and taigas. Drops raw rabbit, rabbit's hide and rarely a rabbit's foot.","image":"https://minecraft.wiki/images/Brown_Rabbit_BE4.png"},{"name":"Donkey","rarity":"common","id":"donkey","subtitle":"Mob","details":"Tamable pack animal that can wear a saddle and carry a chest with 15 slots. A donkey bred with a horse produces a mule.","image":"https://minecraft.wiki/images/Donkey_JE5.png"},{"name":"Mule","rarity":"common","id":"mule","subtitle":"Mob","details":"Offspring of a horse and a donkey. It can wear a chest like a donkey but, like all mules, cannot breed with anything.","image":"https://minecraft.wiki/images/Mule_JE5.png"},{"name":"Ocelot","rarity":"common","id":"ocelot","subtitle":"Mob","details":"Shy jungle mob that gains trust when fed raw cod or raw salmon. It will not follow you, unlike a tamed cat.","image":"https://minecraft.wiki/images/Ocelot_JE2_BE2.png"},{"name":"Bat","rarity":"common","id":"bat","subtitle":"Mob","details":"Ambient flying mob that hangs upside down in dark caves and squeaks. It drops nothing and cannot be tamed or bred.","image":"https://minecraft.wiki/images/Bat_JE4_BE3.gif"},{"name":"Squid","rarity":"common","id":"squid","subtitle":"Mob","details":"Aquatic mob of rivers and oceans that swims in schools and drops an ink sac, used for black dye, when killed.","image":"https://minecraft.wiki/images/Squid_JE2_BE2.gif"},{"name":"Glow Squid","rarity":"common","id":"glow-squid","subtitle":"Mob","details":"Aquatic mob of dark, deep water whose glowing spots are cosmetic. Drops a glow ink sac that makes sign text and item frames glow.","image":"assets/sets/compress/minecraft__glow-squid.webp"},{"name":"Cod","rarity":"common","id":"cod","subtitle":"Mob","details":"Common fish of oceans and rivers that drops raw cod when killed. A cod caught alive in a bucket can be released anywhere.","image":"https://minecraft.wiki/images/Cod.gif"},{"name":"Salmon","rarity":"common","id":"salmon","subtitle":"Mob","details":"Fish that swims up rivers and spawns in oceans and frozen waters. Drops raw salmon, a better food once cooked.","image":"https://minecraft.wiki/images/Salmon.gif"},{"name":"Tropical Fish","rarity":"common","id":"tropical-fish","subtitle":"Mob","details":"Colourful fish of warm oceans, in thousands of colour, pattern and shape combinations. Caught live in a bucket for aquariums.","image":"https://minecraft.wiki/images/Clownfish.png"},{"name":"Pufferfish","rarity":"common","id":"pufferfish","subtitle":"Mob","details":"Warm-ocean fish that inflates and poisons nearby players when threatened. Its item brews potions of water breathing.","image":"https://minecraft.wiki/images/Pufferfish_small.gif"},{"name":"Turtle","rarity":"common","id":"turtle","subtitle":"Mob","details":"Beach mob that lays eggs on sand; the eggs hatch at night. Babies drop a scute as they grow up, five of which make a turtle shell.","image":"https://minecraft.wiki/images/Turtle_JE3_BE1.png"},{"name":"Dirt","rarity":"common","id":"dirt","subtitle":"Block","details":"One of the most common blocks, found under grass almost everywhere. A shovel digs it fastest, and a hoe turns it into farmland.","image":"https://minecraft.wiki/images/Dirt_JE2_BE2.png"},{"name":"Coarse Dirt","rarity":"common","id":"coarse-dirt","subtitle":"Block","details":"Crafted from 2 dirt and 2 gravel. Grass and mycelium will not spread onto it, so it suits paths and giant-tree taiga floors.","image":"https://minecraft.wiki/images/Coarse_Dirt.png"},{"name":"Podzol","rarity":"common","id":"podzol","subtitle":"Block","details":"Topsoil of giant tree taigas where spruce grows. Mushrooms grow on it at any light level, making it handy for mushroom farms.","image":"https://minecraft.wiki/images/Podzol_JE2_BE2.png"},{"name":"Mycelium","rarity":"common","id":"mycelium","subtitle":"Block","details":"Purple topsoil found only in mushroom fields. It spreads to dirt, hosts giant mushrooms and is home turf of the mooshroom.","image":"https://minecraft.wiki/images/Mycelium_JE3_BE3.png"},{"name":"Stone","rarity":"common","id":"stone","subtitle":"Block","details":"Most common underground block. A pickaxe mines it into cobblestone unless the pickaxe has Silk Touch, which yields stone itself.","image":"https://minecraft.wiki/images/Stone_JE5_BE3.png"},{"name":"Cobblestone","rarity":"common","id":"cobblestone","subtitle":"Block","details":"What stone becomes when mined without Silk Touch. Also forms where lava meets water, and builds furnaces and stone tools.","image":"https://minecraft.wiki/images/Cobblestone_JE5_BE3.png"},{"name":"Mossy Cobblestone","rarity":"common","id":"mossy-cobblestone","subtitle":"Block","details":"Moss-covered cobblestone found in dungeons, strongholds and jungle temples. Crafted from cobblestone plus moss or vines.","image":"https://minecraft.wiki/images/Mossy_Cobblestone_JE4_BE2.png"},{"name":"Stone Bricks","rarity":"common","id":"stone-bricks","subtitle":"Block","details":"Smooth building block crafted from 4 stone blocks. Strongholds, jungle temples and igloo basements are built from its variants.","image":"https://minecraft.wiki/images/Stone_Bricks_JE3_BE2.png"},{"name":"Deepslate","rarity":"common","id":"deepslate","subtitle":"Block","details":"Dark stone that replaces stone below y=0. It is tougher than stone, and mining it drops cobbled deepslate instead.","image":"https://minecraft.wiki/images/Deepslate_%28UD%29_JE3_BE2.png"},{"name":"Cobbled Deepslate","rarity":"common","id":"cobbled-deepslate","subtitle":"Block","details":"Mining deepslate drops this instead of the block itself. It can be smelted back to deepslate or crafted into bricks and tiles.","image":"https://minecraft.wiki/images/Cobbled_Deepslate.png"},{"name":"Granite","rarity":"common","id":"granite","subtitle":"Block","details":"Pink-speckled stone found in blobs underground in most biomes. It is crafted from diorite and nether quartz and can be polished.","image":"https://minecraft.wiki/images/Granite.png"},{"name":"Diorite","rarity":"common","id":"diorite","subtitle":"Block","details":"White, black-speckled stone found underground in blobs. Craft it from cobblestone and nether quartz, or polish it for building.","image":"https://minecraft.wiki/images/Diorite.png"},{"name":"Andesite","rarity":"common","id":"andesite","subtitle":"Block","details":"Grey stone found underground in large blobs. A common cave wall block that can be polished for cleaner building projects.","image":"https://minecraft.wiki/images/Andesite.png"},{"name":"Tuff","rarity":"common","id":"tuff","subtitle":"Block","details":"Ash-grey block found in blobs below y=0 around deepslate. It forms the newer tuff bricks used around trial chambers.","image":"https://minecraft.wiki/images/Tuff.png"},{"name":"Sand","rarity":"common","id":"sand","subtitle":"Block","details":"Gravity-affected block of deserts and beaches. Smelts into glass, crafts into TNT and concrete powder, and falls if unsupported.","image":"https://minecraft.wiki/images/Sand_JE5_BE3.png"},{"name":"Red Sand","rarity":"common","id":"red-sand","subtitle":"Block","details":"Orange sand of the badlands, obeying gravity like regular sand. It smelts into glass and crafts into red sandstone.","image":"https://minecraft.wiki/images/Red_Sand_JE3_BE2.png"},{"name":"Gravel","rarity":"common","id":"gravel","subtitle":"Block","details":"Gravity-affected block found underwater, underground and in caves. Digging it has a 10% chance to drop flint instead.","image":"https://minecraft.wiki/images/Gravel_JE5_BE4.png"},{"name":"Clay","rarity":"common","id":"clay","subtitle":"Block","details":"Block dug from river and lake beds, often near sugar cane. Each block breaks into 4 clay balls for bricks or terracotta.","image":"https://minecraft.wiki/images/Clay_JE2_BE2.png"},{"name":"Sandstone","rarity":"common","id":"sandstone","subtitle":"Block","details":"Crafted from 4 sand and found under desert sand, holding it up. Desert temples, wells and warm ocean ruins use it heavily.","image":"https://minecraft.wiki/images/Sandstone_JE6_BE3.png"},{"name":"Red Sandstone","rarity":"common","id":"red-sandstone","subtitle":"Block","details":"Crafted from 4 red sand, with cut, chiseled and smooth variants. It generates naturally in a layer under red sand in the badlands.","image":"https://minecraft.wiki/images/Red_Sandstone_JE4_BE2.png"},{"name":"Terracotta","rarity":"common","id":"terracotta","subtitle":"Block","details":"Made by smelting a clay block, naturally coloured in badlands layers. Eight blocks around a dye recolour the whole batch.","image":"https://minecraft.wiki/images/Terracotta_JE2_BE2.png"},{"name":"Glass","rarity":"common","id":"glass","subtitle":"Block","details":"Made by smelting sand in a furnace. Transparent for windows and bottles, but it shatters with no drop unless mined with Silk Touch.","image":"https://minecraft.wiki/images/Glass_JE4.png"},{"name":"Bricks","rarity":"common","id":"bricks","subtitle":"Block","details":"Building block crafted from 4 individual bricks, with a classic red-brick pattern. Also used for brick stairs, slabs and walls.","image":"https://minecraft.wiki/images/Bricks_JE5_BE3.png"},{"name":"Snow Block","rarity":"common","id":"snow-block","subtitle":"Block","details":"Compact block crafted from 4 snowballs or gathered from snowy ground layers. Two stacked snow blocks plus a carved pumpkin make a snow golem.","image":"https://minecraft.wiki/images/Snow_Block_JE2_BE2.png"},{"name":"Ice","rarity":"common","id":"ice","subtitle":"Block","details":"Frozen water that needs Silk Touch to collect. It is slippery to walk on and melts into water near strong light or heat.","image":"https://minecraft.wiki/images/Ice_JE4_BE6.png"},{"name":"Packed Ice","rarity":"common","id":"packed-ice","subtitle":"Block","details":"Denser ice crafted from 9 ice blocks or found in ice spikes. It never melts, is very slippery, and makes fast boat ice roads.","image":"https://minecraft.wiki/images/Packed_Ice_JE2_BE3.png"},{"name":"Moss Block","rarity":"common","id":"moss-block","subtitle":"Block","details":"Soft green block of lush caves that bone meal spreads to nearby dirt and stone. Moss carpets and flowering azalea grow from it.","image":"https://minecraft.wiki/images/Moss_Block_JE1_BE1.png"},{"name":"Blue Ice","rarity":"common","id":"blue-ice","subtitle":"Block","details":"Crafted from 9 packed ice and found in icebergs. The slipperiest block in the game, it makes the fastest boat highways.","image":"https://minecraft.wiki/images/Blue_Ice_JE1.png"},{"name":"Oak Log","rarity":"common","id":"oak-log","subtitle":"Block","details":"Trunk block of the classic oak, the most common tree in plains and forests. Each log crafts into 4 oak planks.","image":"https://minecraft.wiki/images/Oak_Log_%28UD%29_JE8_BE3.png"},{"name":"Spruce Log","rarity":"common","id":"spruce-log","subtitle":"Block","details":"Trunk of spruce trees in taigas and snowy biomes, often growing very tall. Its dark bark crafts into 4 spruce planks.","image":"https://minecraft.wiki/images/Spruce_Log_%28UD%29_JE8_BE4.png"},{"name":"Birch Log","rarity":"common","id":"birch-log","subtitle":"Block","details":"White bark flecked with black, from birch trees of birch forests and meadows. Each log crafts into 4 pale birch planks.","image":"https://minecraft.wiki/images/Birch_Log_%28UD%29_JE8_BE4.png"},{"name":"Jungle Log","rarity":"common","id":"jungle-log","subtitle":"Block","details":"Trunk of tall jungle trees, sometimes with cocoa pods growing on its sides. Each log crafts into 4 jungle planks.","image":"https://minecraft.wiki/images/Jungle_Log_%28UD%29_JE9_BE4.png"},{"name":"Acacia Log","rarity":"common","id":"acacia-log","subtitle":"Block","details":"Grey-barked trunk of flat-topped acacia trees that lean and branch in the savanna. Each log crafts into 4 orange acacia planks.","image":"https://minecraft.wiki/images/Acacia_Log_%28UD%29_JE8_BE3.png"},{"name":"Dark Oak Log","rarity":"common","id":"dark-oak-log","subtitle":"Block","details":"Trunk of dark oaks in dark forests, which grow only as thick 2x2 trunks from 4 saplings. Their leaves can drop apples.","image":"https://minecraft.wiki/images/Dark_Oak_Log_%28UD%29_JE9_BE4.png"},{"name":"Oak Planks","rarity":"common","id":"oak-planks","subtitle":"Block","details":"The basic building wood, crafted 4 from one oak log. Used for crafting tables, sticks, doors, boats, fences and first tools.","image":"https://minecraft.wiki/images/Oak_Planks_JE7_BE3.png"},{"name":"Spruce Planks","rarity":"common","id":"spruce-planks","subtitle":"Block","details":"Dark brown planks crafted 4 from a spruce log. A favourite for cabins, roofs and rustic builds in cold biomes.","image":"https://minecraft.wiki/images/Spruce_Planks_JE5.png"},{"name":"Birch Planks","rarity":"common","id":"birch-planks","subtitle":"Block","details":"Pale cream planks crafted 4 from a birch log. Their light colour makes them popular for bright floors and modern builds.","image":"https://minecraft.wiki/images/Birch_Planks_JE3_BE2.png"},{"name":"Jungle Planks","rarity":"common","id":"jungle-planks","subtitle":"Block","details":"Pinkish-brown planks crafted 4 from a jungle log. One of the warmer plank tones, matching jungle temples and docks.","image":"https://minecraft.wiki/images/Jungle_Planks_JE3_BE2.png"},{"name":"Acacia Planks","rarity":"common","id":"acacia-planks","subtitle":"Block","details":"Vivid orange planks crafted 4 from an acacia log. They stand out sharply against the grey bark of the acacia trunk.","image":"https://minecraft.wiki/images/Acacia_Planks_JE3_BE2.png"},{"name":"Dark Oak Planks","rarity":"common","id":"dark-oak-planks","subtitle":"Block","details":"Deep, rich brown planks crafted 4 from a dark oak log. The darkest standard planks, prized for libraries and mansion floors.","image":"https://minecraft.wiki/images/Dark_Oak_Planks_JE3_BE2.png"},{"name":"Mangrove Log","rarity":"common","id":"mangrove-log","subtitle":"Block","details":"Trunk of mangroves in muddy swamps, ringed by arching roots above the mud. Grown from propagules, not ordinary saplings.","image":"https://minecraft.wiki/images/Mangrove_Log_%28UD%29_JE1_BE1.png"},{"name":"Cherry Log","rarity":"common","id":"cherry-log","subtitle":"Block","details":"Dark-barked trunk of cherry trees in rare cherry groves, where pink petals drift down. Each log crafts into 4 cherry planks.","image":"https://minecraft.wiki/images/Cherry_Log_%28UD%29_JE1_BE1.png"},{"name":"Mangrove Planks","rarity":"common","id":"mangrove-planks","subtitle":"Block","details":"Warm reddish planks crafted 4 from a mangrove log. The set includes a mangrove door, trapdoor and propagule-grown roots theme.","image":"https://minecraft.wiki/images/Mangrove_Planks_JE1_BE1.png"},{"name":"Cherry Planks","rarity":"common","id":"cherry-planks","subtitle":"Block","details":"Pink planks crafted 4 from a cherry log, with matching pink doors, signs and fences. They debuted with the cherry grove biome.","image":"https://minecraft.wiki/images/Cherry_Planks_JE1_BE1.png"},{"name":"Oak Leaves","rarity":"common","id":"oak-leaves","subtitle":"Block","details":"Canopy of oak trees. If left with no log nearby they decay, dropping saplings, sticks and occasionally an apple.","image":"https://minecraft.wiki/images/Oak_Leaves.png"},{"name":"Spruce Leaves","rarity":"common","id":"spruce-leaves","subtitle":"Block","details":"Dark green canopy of spruce trees, shaped into cones on tall taiga pines. Decay drops spruce saplings for replanting.","image":"https://minecraft.wiki/images/Spruce_Leaves.png"},{"name":"Birch Leaves","rarity":"common","id":"birch-leaves","subtitle":"Block","details":"Canopy of birch trees, a lighter green than oak leaves. Shears or Silk Touch collect the block; otherwise it may drop a sapling.","image":"https://minecraft.wiki/images/Birch_Leaves.png"},{"name":"Jungle Leaves","rarity":"common","id":"jungle-leaves","subtitle":"Block","details":"Dense canopy of jungle giants, home to vines and cocoa pods. Jungle leaves are a prime source of jungle saplings on decay.","image":"https://minecraft.wiki/images/Jungle_Leaves.png"},{"name":"Acacia Leaves","rarity":"common","id":"acacia-leaves","subtitle":"Block","details":"Canopy of savanna acacias, spread flat like an umbrella over the grassland. Decay can drop an acacia sapling and sticks.","image":"https://minecraft.wiki/images/Acacia_Leaves.png"},{"name":"Dark Oak Leaves","rarity":"common","id":"dark-oak-leaves","subtitle":"Block","details":"Canopy of the 2x2 dark oak, denser and darker than oak leaves. It has a notably good chance to drop an apple as it decays.","image":"https://minecraft.wiki/images/Dark_Oak_Leaves.png"},{"name":"Cherry Leaves","rarity":"common","id":"cherry-leaves","subtitle":"Block","details":"Pink blossom canopy of cherry grove trees. Standing under them sheds falling petal particles onto the ground below.","image":"https://minecraft.wiki/images/Cherry_Leaves_JE2.png"},{"name":"Mangrove Leaves","rarity":"common","id":"mangrove-leaves","subtitle":"Block","details":"Canopy of swamp mangroves. A propagule can ripen hanging beneath the leaves, then drop and plant itself in mud or shallow water.","image":"https://minecraft.wiki/images/Mangrove_Leaves.png"},{"name":"Poppy","rarity":"common","id":"poppy","subtitle":"Plant","details":"Short red flower of plains, forests and meadows. It crafts into red dye, and iron golems sometimes offer one to a villager.","image":"https://minecraft.wiki/images/Poppy_JE8_BE2.png"},{"name":"Dandelion","rarity":"common","id":"dandelion","subtitle":"Plant","details":"Short yellow flower common in plains and forests. It crafts into yellow dye and brews a suspicious stew of saturation.","image":"https://minecraft.wiki/images/Dandelion_JE7_BE4.png"},{"name":"Red Tulip","rarity":"common","id":"red-tulip","subtitle":"Plant","details":"Red tulip found in flower forests and plains. Tulips grow in colour patches, and this one crafts into red dye.","image":"https://minecraft.wiki/images/Red_Tulip_JE7_BE2.png"},{"name":"Orange Tulip","rarity":"common","id":"orange-tulip","subtitle":"Plant","details":"Orange tulip found in flower forests and plains, growing in patches of a single colour. It crafts into orange dye.","image":"https://minecraft.wiki/images/Orange_Tulip_JE7_BE2.png"},{"name":"White Tulip","rarity":"common","id":"white-tulip","subtitle":"Plant","details":"White tulip found in flower forests and plains, growing in single-colour patches. It crafts into light grey dye.","image":"https://minecraft.wiki/images/White_Tulip_JE7_BE2.png"},{"name":"Pink Tulip","rarity":"common","id":"pink-tulip","subtitle":"Plant","details":"Pink tulip found in flower forests and plains, growing in single-colour patches. It crafts into pink dye.","image":"https://minecraft.wiki/images/Pink_Tulip_JE7_BE2.png"},{"name":"Oxeye Daisy","rarity":"common","id":"oxeye-daisy","subtitle":"Plant","details":"White-petalled flower with a yellow centre, found in plains and flower forests. It crafts into light grey dye.","image":"https://minecraft.wiki/images/Oxeye_Daisy_JE7_BE2.png"},{"name":"Cornflower","rarity":"common","id":"cornflower","subtitle":"Plant","details":"Blue flower of plains and sunflower plains with slender green stems. It crafts into blue dye, a colour few flowers provide.","image":"https://minecraft.wiki/images/Cornflower_JE1_BE1.png"},{"name":"Lily of the Valley","rarity":"common","id":"lily-of-the-valley","subtitle":"Plant","details":"White bell flower of flower forests and birch forests. It crafts into white dye and makes a suspicious stew that poisons.","image":"https://minecraft.wiki/images/Lily_of_the_Valley_JE1_BE1.png"},{"name":"Azure Bluet","rarity":"common","id":"azure-bluet","subtitle":"Plant","details":"Tiny white cluster flower of plains, taigas and snowy plains. It crafts into light grey dye despite its blue-sounding name.","image":"https://minecraft.wiki/images/Azure_Bluet_JE7_BE2.png"},{"name":"Allium","rarity":"common","id":"allium","subtitle":"Plant","details":"Purple pom-pom flower found only in flower forests. It crafts into magenta dye and makes a fire-resistance suspicious stew.","image":"https://minecraft.wiki/images/Allium_JE7_BE2.png"},{"name":"Blue Orchid","rarity":"common","id":"blue-orchid","subtitle":"Plant","details":"Blue flower found only in swamps, on grass near water. It crafts into light blue dye; no other flower shares its swamp home.","image":"https://minecraft.wiki/images/Blue_Orchid_JE7_BE4.png"},{"name":"Sunflower","rarity":"common","id":"sunflower","subtitle":"Plant","details":"Two-block-tall yellow flower found only in sunflower plains, always facing east. It crafts into two yellow dye.","image":"https://minecraft.wiki/images/Sunflower_JE6.png"},{"name":"Lilac","rarity":"common","id":"lilac","subtitle":"Plant","details":"Two-block-tall flower of forests and flower forests with purple blooms. It crafts into two magenta dye.","image":"https://minecraft.wiki/images/Lilac_JE4_BE2.png"},{"name":"Rose Bush","rarity":"common","id":"rose-bush","subtitle":"Plant","details":"Two-block-tall red flower of forests, taigas and flower forests. It crafts into two red dye, twice a poppy's yield.","image":"https://minecraft.wiki/images/Rose_Bush_JE4_BE3.png"},{"name":"Peony","rarity":"common","id":"peony","subtitle":"Plant","details":"Two-block-tall pink flower of forests and meadows. It crafts into two pink dye and grows on grass blocks only.","image":"https://minecraft.wiki/images/Peony_JE4_BE3.png"},{"name":"Fern","rarity":"common","id":"fern","subtitle":"Plant","details":"Green ground plant of taigas, jungles and lush caves. Shears harvest it, and bone meal on it grows a large fern.","image":"https://minecraft.wiki/images/Fern_JE6.png"},{"name":"Dead Bush","rarity":"common","id":"dead-bush","subtitle":"Plant","details":"Dry shrub of deserts and badlands that grows on sand and terracotta. Breaking it drops sticks instead of the bush itself.","image":"https://minecraft.wiki/images/Dead_Bush_JE6_BE4.png"},{"name":"Sugar Cane","rarity":"common","id":"sugar-cane","subtitle":"Plant","details":"Tall green reed that grows up to 3 high on dirt or sand right beside water. It crafts into paper and sugar.","image":"https://minecraft.wiki/images/Sugar_Cane_JE2_BE2.png"},{"name":"Cactus","rarity":"common","id":"cactus","subtitle":"Plant","details":"Spiky desert plant that damages anything touching it and breaks items dropped on it. Smelting it yields green dye.","image":"https://minecraft.wiki/images/Cactus_JE4.png"},{"name":"Bamboo","rarity":"common","id":"bamboo","subtitle":"Plant","details":"Fast-growing jungle plant eaten by pandas and found near them. It makes scaffolding, sticks and bamboo planks and blocks.","image":"https://minecraft.wiki/images/Leafless_Old_Bamboo_JE1_BE1.png"},{"name":"Vine","rarity":"common","id":"vine","subtitle":"Plant","details":"Climbing plant that spreads down jungle tree trunks and swamp oaks. Shears harvest it; players can climb it like a ladder.","image":"https://minecraft.wiki/images/Vines_JE2_BE2.png"},{"name":"Lily Pad","rarity":"common","id":"lily-pad","subtitle":"Plant","details":"Flat pad that sits on swamp and mangrove swamp water. Players can stand on it, but fast boats break straight through it.","image":"https://minecraft.wiki/images/Lily_Pad_JE3.png"},{"name":"Kelp","rarity":"common","id":"kelp","subtitle":"Plant","details":"Underwater plant of oceans that grows tall toward the surface. Dried in a furnace it becomes food and a long-burning fuel block.","image":"https://minecraft.wiki/images/Kelp_JE3_BE2.gif"},{"name":"Stick","rarity":"common","id":"stick","subtitle":"Item","details":"Basic crafting stick made from 2 planks. It is the handle for tools and weapons and builds torches, fences, ladders and signs.","image":"https://minecraft.wiki/images/Stick_JE1_BE1.png"},{"name":"Coal","rarity":"common","id":"coal","subtitle":"Item","details":"Fuel dug from coal ore, common at almost any depth. One piece smelts 8 items and crafts torches, campfires and fire charges.","image":"https://minecraft.wiki/images/Coal_JE4_BE3.png"},{"name":"Charcoal","rarity":"common","id":"charcoal","subtitle":"Item","details":"Coal substitute made by smelting any log in a furnace. It smelts 8 items and makes torches, but cannot be traded to villagers.","image":"https://minecraft.wiki/images/Charcoal_JE4_BE4.png"},{"name":"String","rarity":"common","id":"string","subtitle":"Item","details":"Dropped by spiders and cave spiders or cut from cobwebs with shears. It crafts bows, fishing rods, leads, looms and wool.","image":"https://minecraft.wiki/images/String_JE2_BE2.png"},{"name":"Bone","rarity":"common","id":"bone","subtitle":"Item","details":"Dropped by skeletons, strays and wither skeletons, or fished up as junk. It crafts bone meal and can tame wild wolves.","image":"https://minecraft.wiki/images/Bone_JE3_BE2.png"},{"name":"Feather","rarity":"common","id":"feather","subtitle":"Item","details":"Dropped by chickens, parrots and foxes holding one. Four uses include arrows, books and quills, brushes and firework effects.","image":"https://minecraft.wiki/images/Feather_JE3_BE2.png"},{"name":"Leather","rarity":"common","id":"leather","subtitle":"Item","details":"Dropped by cows, horses, donkeys, mules and llamas, or crafted from 4 rabbit hide. It makes armour, books and item frames.","image":"https://minecraft.wiki/images/Leather_JE2_BE2.png"},{"name":"Paper","rarity":"common","id":"paper","subtitle":"Item","details":"Crafted from 3 sugar cane in a row. It makes books, maps, banners and firework rockets, and trades well to librarians.","image":"https://minecraft.wiki/images/Paper_JE2_BE2.png"},{"name":"Sugar","rarity":"common","id":"sugar","subtitle":"Item","details":"Refined from sugar cane or a honey bottle. It bakes cakes and pumpkin pie and brews fermented spider eyes and speed potions.","image":"https://minecraft.wiki/images/Sugar_JE2_BE2.png"},{"name":"Flint","rarity":"common","id":"flint","subtitle":"Item","details":"Sometimes dug from gravel instead of the block, with a 10% base chance. It crafts flint and steel, arrows and fire charges.","image":"https://minecraft.wiki/images/Flint_JE3_BE3.png"},{"name":"Brick","rarity":"common","id":"brick","subtitle":"Item","details":"Single fired brick made by smelting a clay ball. Four bricks craft the bricks block, and three bricks craft a flower pot.","image":"https://minecraft.wiki/images/Brick_JE2_BE2.png"},{"name":"Gunpowder","rarity":"common","id":"gunpowder","subtitle":"Item","details":"Dropped by creepers, ghasts and witches. It crafts TNT and firework stars and is required for splash and lingering potions.","image":"https://minecraft.wiki/images/Gunpowder_JE2_BE2.png"},{"name":"Rotten Flesh","rarity":"common","id":"rotten-flesh","subtitle":"Item","details":"Dropped by zombies and their variants. Eating it restores 4 hunger but has an 80% chance to inflict Hunger; dogs eat it safely.","image":"https://minecraft.wiki/images/Rotten_Flesh_JE3_BE2.png"},{"name":"Spider Eye","rarity":"common","id":"spider-eye","subtitle":"Item","details":"Dropped by spiders and witches, poisonous if eaten. Fermented with sugar and a brown mushroom, it brews corrupted potions.","image":"https://minecraft.wiki/images/Spider_Eye_JE2_BE2.png"},{"name":"Egg","rarity":"common","id":"egg","subtitle":"Item","details":"Laid by chickens every 5 to 10 minutes. Throwing one has a 1-in-8 chance to hatch a baby chick; eggs also bake cakes.","image":"https://minecraft.wiki/images/Egg_JE2_BE2.png"},{"name":"Ink Sac","rarity":"common","id":"ink-sac","subtitle":"Item","details":"Dropped by squids when killed. It crafts black dye, writes books and quills, and darkens the text on signs.","image":"https://minecraft.wiki/images/Ink_Sac_JE2_BE2.png"},{"name":"Glow Ink Sac","rarity":"common","id":"glow-ink-sac","subtitle":"Item","details":"Dropped by glow squids when killed. It makes item frame contents glow and makes sign text glow with a bright outline.","image":"https://minecraft.wiki/images/Glow_Ink_Sac_JE1_BE1.png"},{"name":"Bone Meal","rarity":"common","id":"bone-meal","subtitle":"Item","details":"Crafted from a bone or made in a composter. Used as fertiliser it instantly grows most crops, saplings and plants to maturity.","image":"https://minecraft.wiki/images/Bone_Meal_JE3_BE3.png"},{"name":"Snowball","rarity":"common","id":"snowball","subtitle":"Item","details":"Gathered by shovelling snow layers or snow golems' trails. Thrown snowballs knock mobs back and hurt blazes but not players.","image":"https://minecraft.wiki/images/Snowball_JE3_BE3.png"},{"name":"Arrow","rarity":"common","id":"arrow","subtitle":"Item","details":"Ammunition for bows, crossbows and dispensers, crafted from flint, a stick and a feather. Skeletons also drop them when killed.","image":"https://minecraft.wiki/images/Arrow_JE2_BE1.png"},{"name":"Apple","rarity":"common","id":"apple","subtitle":"Food","details":"Rare drop when oak or dark oak leaves decay, about 1 in 200. It restores 4 hunger and crafts the golden apple.","image":"https://minecraft.wiki/images/Apple_JE3_BE3.png"},{"name":"Bread","rarity":"common","id":"bread","subtitle":"Food","details":"Staple food crafted from 3 wheat, restoring 5 hunger. Farmer villagers bake and trade it, and it stacks neatly for journeys.","image":"https://minecraft.wiki/images/Bread_JE3_BE3.png"},{"name":"Raw Beef","rarity":"common","id":"raw-beef","subtitle":"Food","details":"Dropped 1 to 3 by cows and mooshrooms when killed. It restores 3 hunger raw, or cook it into steak, worth 8 hunger.","image":"https://minecraft.wiki/images/Raw_Beef_JE4_BE3.png"},{"name":"Raw Porkchop","rarity":"common","id":"raw-porkchop","subtitle":"Food","details":"Dropped 1 to 3 by pigs when killed. It restores 3 hunger raw; cooking it into a porkchop raises that to 8 hunger.","image":"https://minecraft.wiki/images/Raw_Porkchop_JE3_BE3.png"},{"name":"Raw Chicken","rarity":"common","id":"raw-chicken","subtitle":"Food","details":"Dropped by chickens when killed. It restores 2 hunger but carries a 30% chance of the Hunger effect until it is cooked.","image":"https://minecraft.wiki/images/Raw_Chicken_JE3_BE3.png"},{"name":"Raw Mutton","rarity":"common","id":"raw-mutton","subtitle":"Food","details":"Dropped 1 or 2 by sheep when killed. It restores 2 hunger raw; cooked mutton restores 6 and is far more filling.","image":"https://minecraft.wiki/images/Raw_Mutton_JE3_BE2.png"},{"name":"Raw Cod","rarity":"common","id":"raw-cod","subtitle":"Food","details":"Dropped by cod mobs and from fishing. It restores 2 hunger raw; cooked cod restores 5 and can be fed to cats and ocelots.","image":"https://minecraft.wiki/images/Raw_Cod_JE4_BE2.png"},{"name":"Raw Salmon","rarity":"common","id":"raw-salmon","subtitle":"Food","details":"Dropped by salmon and polar bears. It restores 2 hunger raw; cooked salmon restores 6 hunger and more saturation.","image":"https://minecraft.wiki/images/Raw_Salmon_JE2_BE2.png"},{"name":"Potato","rarity":"common","id":"potato","subtitle":"Food","details":"Crop grown from potato plants in villages, also dropped rarely by zombies. It restores 1 hunger raw, or bake it for 5.","image":"https://minecraft.wiki/images/Potato_JE3_BE2.png"},{"name":"Carrot","rarity":"common","id":"carrot","subtitle":"Food","details":"Crop from village farms, also a rare zombie drop. It restores 3 hunger and breeds pigs and rabbits; horses eat it to heal.","image":"https://minecraft.wiki/images/Carrot_JE3_BE2.png"},{"name":"Beetroot","rarity":"common","id":"beetroot","subtitle":"Food","details":"Crop grown in village farms from beetroot seeds. It restores just 1 hunger alone, but 6 in a bowl of beetroot soup.","image":"https://minecraft.wiki/images/Beetroot_JE2_BE2.png"},{"name":"Melon Slice","rarity":"common","id":"melon-slice","subtitle":"Food","details":"One slice of a melon block, which breaks into 3 to 7 slices. It restores 2 hunger and crafts melon seeds and glistering melon.","image":"https://minecraft.wiki/images/Melon_Slice_JE2_BE2.png"},{"name":"Sweet Berries","rarity":"common","id":"sweet-berries","subtitle":"Food","details":"Harvested from a mature sweet berry bush in taigas, restoring 2 hunger. Picking a ripe bush does not hurt; walking into one does.","image":"https://minecraft.wiki/images/Sweet_Berries_JE1_BE1.png"},{"name":"Cookie","rarity":"common","id":"cookie","subtitle":"Food","details":"Sweet snack crafted from 2 wheat and cocoa beans, restoring 2 hunger but very little saturation. Never feed one to a parrot.","image":"https://minecraft.wiki/images/Cookie_JE2_BE2.png"},{"name":"Poisonous Potato","rarity":"common","id":"poisonous-potato","subtitle":"Food","details":"Uncommon variant with a 2% chance when harvesting potatoes. Eating it restores 2 hunger but has a 60% chance to poison you.","image":"https://minecraft.wiki/images/Poisonous_Potato_JE3_BE2.png"},{"name":"Wheat","rarity":"common","id":"wheat","subtitle":"Item","details":"Crop grown from seeds broken from grass. It bakes bread, bales into hay, and breeds cows, sheep, goats and mooshrooms.","image":"https://minecraft.wiki/images/Wheat_JE2_BE2.png"},{"name":"Pumpkin Seeds","rarity":"common","id":"pumpkin-seeds","subtitle":"Item","details":"Obtained 4 at a time by crafting a pumpkin. Planted on farmland, the stem grows a new pumpkin on adjacent dirt or grass.","image":"https://minecraft.wiki/images/Pumpkin_Seeds_JE1_BE1.png"},{"name":"Melon Seeds","rarity":"common","id":"melon-seeds","subtitle":"Item","details":"Crafted from a single melon slice. Planted on farmland, the stem grows a full melon block on an adjacent empty spot.","image":"https://minecraft.wiki/images/Melon_Seeds_JE2_BE2.png"},{"name":"Wooden Sword","rarity":"common","id":"wooden-sword","subtitle":"Weapon","details":"Starter weapon crafted from 2 planks and a stick, dealing 4 damage in Java Edition. It wears out after 59 uses.","image":"https://minecraft.wiki/images/Wooden_Sword_JE2_BE2.png"},{"name":"Wooden Pickaxe","rarity":"common","id":"wooden-pickaxe","subtitle":"Tool","details":"First pickaxe, crafted from 3 planks and 2 sticks. It can mine stone and coal ore, unlocking cobblestone and better tools.","image":"https://minecraft.wiki/images/Wooden_Pickaxe_JE3_BE3.png"},{"name":"Wooden Axe","rarity":"common","id":"wooden-axe","subtitle":"Tool","details":"Starter axe crafted from 3 planks and 2 sticks. It chops logs quickly and strips bark, but its 59 durability runs out fast.","image":"https://minecraft.wiki/images/Wooden_Axe_JE2_BE2.png"},{"name":"Wooden Shovel","rarity":"common","id":"wooden-shovel","subtitle":"Tool","details":"Starter shovel crafted from 1 plank and 2 sticks. It digs dirt, sand and gravel fast and flattens grass into a dirt path.","image":"https://minecraft.wiki/images/Wooden_Shovel_JE2_BE2.png"},{"name":"Wooden Hoe","rarity":"common","id":"wooden-hoe","subtitle":"Tool","details":"Starter hoe crafted from 2 planks and 2 sticks. It tills dirt and grass into farmland and harvests leaves and sculk quickly.","image":"https://minecraft.wiki/images/Wooden_Hoe_JE3_BE3.png"},{"name":"Stone Sword","rarity":"common","id":"stone-sword","subtitle":"Weapon","details":"Early weapon crafted from 2 cobblestone and a stick, dealing 5 damage in Java Edition. A clear step up from the wooden sword.","image":"https://minecraft.wiki/images/Stone_Sword_JE2_BE2.png"},{"name":"Stone Pickaxe","rarity":"common","id":"stone-pickaxe","subtitle":"Tool","details":"Workhorse pickaxe crafted from 3 cobblestone and 2 sticks. It can mine iron, copper and lapis ores the wooden pick cannot finish.","image":"https://minecraft.wiki/images/Stone_Pickaxe_JE2_BE2.png"},{"name":"Stone Axe","rarity":"common","id":"stone-axe","subtitle":"Tool","details":"Axe crafted from 3 cobblestone and 2 sticks. It chops wood, strips logs, disables shields and hits for 9 damage in Java Edition.","image":"https://minecraft.wiki/images/Stone_Axe_JE2_BE2.png"},{"name":"Stone Shovel","rarity":"common","id":"stone-shovel","subtitle":"Tool","details":"Shovel crafted from 1 cobblestone and 2 sticks, with 131 durability. It digs soft blocks fast and makes dirt paths.","image":"https://minecraft.wiki/images/Stone_Shovel_JE2_BE2.png"},{"name":"Stone Hoe","rarity":"common","id":"stone-hoe","subtitle":"Tool","details":"Hoe crafted from 2 cobblestone and 2 sticks, with 131 durability. It tills farmland and breaks leaves, hay and sculk quickly.","image":"https://minecraft.wiki/images/Stone_Hoe_JE2_BE2.png"},{"name":"Leather Armor","rarity":"common","id":"leather-armor","subtitle":"Armor","details":"Weakest armour set, crafted from leather and dyable almost any colour. A full set also keeps you from freezing in powder snow.","image":"https://minecraft.wiki/images/Leather_Tunic_JE3_BE2.png"},{"name":"Torch","rarity":"common","id":"torch","subtitle":"Item","details":"Light source crafted from coal or charcoal on a stick, making 4. Its light level of 14 keeps most hostile mobs from spawning nearby.","image":"https://minecraft.wiki/images/Torch.gif"},{"name":"Plains","rarity":"common","id":"plains","subtitle":"Biome","details":"Flat, grassy biome dotted with flowers, oak trees and villages. Horses, donkeys and bees are common, and it is ideal for building.","image":"assets/sets/compress/minecraft__plains.webp"},{"name":"Forest","rarity":"common","id":"forest","subtitle":"Biome","details":"Temperate biome of oak and birch trees, tall grass and flowers. Bee nests hang from its trees, and wolves roam its clearings.","image":"assets/sets/compress/minecraft__forest.webp"},{"name":"Taiga","rarity":"common","id":"taiga","subtitle":"Biome","details":"Cold forest of spruce trees, podzol patches, ferns and sweet berry bushes. Foxes and wolves roam it, and villages use spruce wood.","image":"assets/sets/compress/minecraft__taiga.webp"},{"name":"River","rarity":"common","id":"river","subtitle":"Biome","details":"Water biome cutting through the land, lined with clay, sugar cane and seagrass. Salmon swim it and drowned lurk beneath it.","image":"assets/sets/compress/minecraft__river.webp"},{"name":"Beach","rarity":"common","id":"beach","subtitle":"Biome","details":"Sandy shore where land meets ocean, often with gravel patches. Turtles nest here, and buried treasure maps point to its sands.","image":"assets/sets/compress/minecraft__beach.webp"},{"name":"Savanna","rarity":"common","id":"savanna","subtitle":"Biome","details":"Warm, dry grassland of flat-topped acacia trees and tall grass where rain never falls. Horses, llamas and armadillos live here.","image":"assets/sets/compress/minecraft__savanna.webp"},{"name":"Snowy Plains","rarity":"common","id":"snowy-plains","subtitle":"Biome","details":"Flat, snow-covered biome where rabbits and polar bears roam. Igloos and snowy villages generate here, and strays prowl at night.","image":"assets/sets/compress/minecraft__snowy-plains.webp"}]});
